window.HEIR_DECLS=[{"id":"1-samuel-2-26","ref":"1 Samuel 2:26","kjv":"And the child Samuel grew on, and was in favour both with the LORD, and also with men.","say":"As I grow, I grow in favour with God and with people.","theme":"blessed-favour","when":"growing up","mean":"Just like little Samuel, I can grow up loved by God and liked by others.","age":"all","tags":["blessed-favour"]},{"id":"deuteronomy-28-6","ref":"Deuteronomy 28:6","kjv":"Blessed shalt thou be when thou comest in, and blessed shalt thou be when thou goest out.","say":"I am blessed when I come in, and I am blessed when I go out.","theme":"blessed-favour","when":"leaving the house","mean":"God's blessing is with me going out and coming home.","age":"4-6","tags":["blessed-favour"]},{"id":"ephesians-1-3","ref":"Ephesians 1:3","kjv":"Blessed be the God and Father of our Lord Jesus Christ, who hath blessed us with all spiritual blessings in heavenly places in Christ:","say":"God has blessed me with every spiritual blessing in Jesus.","theme":"blessed-favour","when":"knowing who I am in Jesus","mean":"Because I belong to Jesus, God has already given me every good spiritual blessing.","age":"7-9","tags":["blessed-favour"]},{"id":"genesis-39-21","ref":"Genesis 39:21","kjv":"But the LORD was with Joseph, and shewed him mercy, and gave him favour in the sight of the keeper of the prison.","say":"God is with me and gives me favour, just like He was with Joseph.","theme":"blessed-favour","when":"a new or hard place","mean":"Even when Joseph was in a hard place, God stayed near and made people kind to him; God does that for me too.","age":"all","tags":["blessed-favour"]},{"id":"jeremiah-17-7","ref":"Jeremiah 17:7","kjv":"Blessed is the man that trusteth in the LORD, and whose hope the LORD is.","say":"I am blessed when I trust in the Lord and put my hope in Him.","theme":"blessed-favour","when":"when I feel worried","mean":"When I trust God and put my hope in Him, He makes me truly blessed and happy.","age":"all","tags":["blessed-favour"]},{"id":"luke-2-52","ref":"Luke 2:52","kjv":"And Jesus increased in wisdom and stature, and in favour with God and man.","say":"Just like Jesus, I grow in wisdom and in favour with God and people.","theme":"blessed-favour","when":"birthday","mean":"Jesus grew up as a child, loved by God and liked by people, and I can grow that way too.","age":"all","tags":["blessed-favour","wise-learner"]},{"id":"numbers-6-24","ref":"Numbers 6:24","kjv":"The LORD bless thee, and keep thee:","say":"The Lord blesses me and keeps me safe.","theme":"blessed-favour","when":"bedtime","mean":"God wants good for me and watches over me while I rest.","age":"4-6","tags":["blessed-favour"]},{"id":"proverbs-10-22","ref":"Proverbs 10:22","kjv":"The blessing of the LORD, it maketh rich, and he addeth no sorrow with it.","say":"God's blessing is the best riches of all, and it never brings me sorrow.","theme":"blessed-favour","when":"wanting more","mean":"God's blessing is the truest kind of rich, and unlike money it never leaves you sad.","age":"7-9","tags":["blessed-favour"]},{"id":"proverbs-3-4","ref":"Proverbs 3:4","kjv":"So shalt thou find favour and good understanding in the sight of God and man.","say":"When I walk with God, I find favour with Him and with people.","theme":"blessed-favour","when":"making friends","mean":"As I love God and stay kind and truthful, He gives me favour with Him and with people.","age":"all","tags":["blessed-favour"]},{"id":"psalm-23-6","ref":"Psalms 23:6","kjv":"Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the LORD for ever.","say":"God's goodness and mercy follow me all the days of my life.","theme":"blessed-favour","when":"a new place","mean":"Everywhere I go, God's goodness and mercy keep following me every day of my life.","age":"all","tags":["blessed-favour"]},{"id":"psalm-5-12","ref":"Psalms 5:12","kjv":"For thou, LORD, wilt bless the righteous; with favour wilt thou compass him as with a shield.","say":"God's favour wraps all around me, like a shield.","theme":"blessed-favour","when":"feeling afraid","mean":"God's kindness goes right around me to keep me safe, the way a shield does.","age":"all","tags":["blessed-favour"]},{"id":"psalms-103-4","ref":"Psalms 103:4","kjv":"Who redeemeth thy life from destruction; who crowneth thee with lovingkindness and tender mercies;","say":"God crowns me with His lovingkindness and tender mercy.","theme":"blessed-favour","when":"feeling unloved","mean":"God places His gentle love over me like a crown.","age":"all","tags":["blessed-favour"]},{"id":"psalms-115-13","ref":"Psalms 115:13","kjv":"He will bless them that fear the LORD, both small and great.","say":"Because I love the Lord, He blesses me, even though I am small.","theme":"blessed-favour","when":"feeling too little","mean":"God blesses everyone who loves Him, big or little; being small is okay.","age":"4-6","tags":["blessed-favour"]},{"id":"psalms-84-11","ref":"Psalms 84:11","kjv":"For the LORD God is a sun and shield: the LORD will give grace and glory: no good thing will he withhold from them that walk uprightly.","say":"God is my sun and my shield, and as I walk with Him He gives me every good thing I truly need.","theme":"blessed-favour","when":"feeling left out","mean":"When I follow God, He holds back nothing that is truly good for me.","age":"7-9","tags":["blessed-favour"]},{"id":"1-chronicles-28-20","ref":"1 Chronicles 28:20","kjv":"And David said to Solomon his son, Be strong and of good courage, and do it: fear not, nor be dismayed: for the LORD God, even my God, will be with thee; he will not fail thee, nor forsake thee, until thou hast finished all the work for the service of the house of the LORD.","say":"I can be brave for a big job, because God is with me and will not fail me.","theme":"brave-courage","when":"a big task","mean":"God helps me be brave and finish the big thing in front of me.","age":"7-9","tags":["brave-courage"]},{"id":"1-corinthians-16-13","ref":"1 Corinthians 16:13","kjv":"Watch ye, stand fast in the faith, quit you like men, be strong.","say":"I stay awake and brave, standing strong in what I believe.","theme":"brave-courage","when":"standing up for what is right","mean":"God tells me to stay alert, hold tight to my faith, and be strong and brave.","age":"7-9","tags":["brave-courage"]},{"id":"2-chronicles-32-7","ref":"2 Chronicles 32:7","kjv":"Be strong and courageous, be not afraid nor dismayed for the king of Assyria, nor for all the multitude that is with him: for there be more with us than with him:","say":"I am strong and brave, because God who is with me is greater than anything against me.","theme":"brave-courage","when":"facing something big","mean":"There is more help on God's side than anything that comes against me, so I can be brave.","age":"7-9","tags":["brave-courage"]},{"id":"2-timothy-1-7","ref":"2 Timothy 1:7","kjv":"For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.","say":"I am not afraid, because God gave me power, love, and a calm mind.","theme":"brave-courage","when":"afraid","mean":"Fear does not come from God; He gives me power, love, and a peaceful heart instead.","age":"7-9","tags":["brave-courage","wise-learner"]},{"id":"isaiah-12-2","ref":"Isaiah 12:2","kjv":"Behold, God is my salvation; I will trust, and not be afraid: for the LORD JEHOVAH is my strength and my song; he also is become my salvation.","say":"God is my strength and my song; I trust Him, so I am not afraid.","theme":"brave-courage","when":"afraid","mean":"I can trust God to save me, so I don't need to be scared.","age":"7-9","tags":["brave-courage"]},{"id":"isaiah-41-10","ref":"Isaiah 41:10","kjv":"Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.","say":"I am not afraid, because God is with me and holds me up with His strong right hand.","theme":"brave-courage","when":"afraid","mean":"God is right here with me and promises to strengthen me and hold me up.","age":"4-6","tags":["brave-courage","wise-learner"]},{"id":"joshua-1-9","ref":"Joshua 1:9","kjv":"Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest.","say":"I can be strong and brave, because God is with me everywhere I go.","theme":"brave-courage","when":"first day in a new place","mean":"God goes with me wherever I am, so I can be strong and brave.","age":"all","tags":["brave-courage","wise-learner"]},{"id":"mark-6-50","ref":"Mark 6:50","kjv":"For they all saw him, and were troubled. And immediately he talked with them, and saith unto them, Be of good cheer: it is I; be not afraid.","say":"I can cheer up and not be afraid, because Jesus is right here with me.","theme":"brave-courage","when":"scared or worried","mean":"Jesus told His frightened friends to cheer up and not be afraid because He was with them, and He is with me too.","age":"4-6","tags":["brave-courage"]},{"id":"proverbs-28-1","ref":"Proverbs 28:1","kjv":"The wicked flee when no man pursueth: but the righteous are bold as a lion.","say":"I am as bold as a lion, because I belong to God.","theme":"brave-courage","when":"needing courage","mean":"Those who belong to God and love to do right can be brave and strong, like a lion.","age":"4-6","tags":["brave-courage"]},{"id":"psalm-118-6","ref":"Psalms 118:6","kjv":"The LORD is on my side; I will not fear: what can man do unto me?","say":"God is on my side, so I will not be afraid of anyone.","theme":"brave-courage","when":"bullied","mean":"Because God is with me, I do not need to be scared of anybody.","age":"4-6","tags":["brave-courage"]},{"id":"psalm-23-4","ref":"Psalms 23:4","kjv":"Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me.","say":"Even in the dark, I am not afraid, because God is with me.","theme":"brave-courage","when":"dark or scary","mean":"Even in scary times, God walks right beside me, so I do not have to be afraid.","age":"all","tags":["brave-courage"]},{"id":"psalm-27-1","ref":"Psalms 27:1","kjv":"The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?","say":"God is my light and my strength, so I do not need to be afraid.","theme":"brave-courage","when":"bedtime","mean":"God is my light and keeps me strong, so I don't need to be scared, even in the dark.","age":"all","tags":["brave-courage","wise-learner"]},{"id":"psalm-31-24","ref":"Psalms 31:24","kjv":"Be of good courage, and he shall strengthen your heart, all ye that hope in the LORD.","say":"I am brave, and God makes my heart strong, because I hope in Him.","theme":"brave-courage","when":"waiting","mean":"When I keep hoping in God, He makes me strong on the inside.","age":"7-9","tags":["brave-courage"]},{"id":"1-corinthians-13-4","ref":"1 Corinthians 13:4","kjv":"Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up,","say":"Because I love, I am patient and kind.","theme":"calm-self-control","when":"being patient","mean":"Real love waits patiently and treats others kindly.","age":"all","tags":["calm-self-control","friends-family"]},{"id":"ecclesiastes-7-9","ref":"Ecclesiastes 7:9","kjv":"Be not hasty in thy spirit to be angry: for anger resteth in the bosom of fools.","say":"I don't rush to get angry. I slow down and stay calm.","theme":"calm-self-control","when":"quick temper","mean":"Being quick to anger is not wise, so I take my time and stay calm.","age":"all","tags":["calm-self-control"]},{"id":"galatians-5-23","ref":"Galatians 5:23","kjv":"Meekness, temperance: against such there is no law.","say":"God's Spirit helps me to be gentle and to have self-control.","theme":"calm-self-control","when":"self-control","mean":"Gentleness and self-control grow in me because God's Spirit is helping me.","age":"all","tags":["calm-self-control"]},{"id":"james-1-19","ref":"James 1:19","kjv":"Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath:","say":"I am quick to listen, slow to speak, and slow to get angry.","theme":"calm-self-control","when":"listening","mean":"God wants me to listen first, speak carefully, and not rush into anger.","age":"all","tags":["calm-self-control","friends-family"]},{"id":"mark-4-39","ref":"Mark 4:39","kjv":"And he arose, and rebuked the wind, and said unto the sea, Peace, be still. And the wind ceased, and there was a great calm.","say":"Jesus calmed a wild storm by saying, 'Peace, be still,' and He can calm the big feelings inside me too.","theme":"calm-self-control","when":"big feelings","mean":"Jesus calmed a scary storm with His words, and He can calm the storms inside me too.","age":"all","tags":["calm-self-control"]},{"id":"proverbs-12-18","ref":"Proverbs 12:18","kjv":"There is that speaketh like the piercings of a sword: but the tongue of the wise is health.","say":"My words are wise and kind, so they help and heal instead of hurting.","theme":"calm-self-control","when":"when words can hurt","mean":"Wise, gentle words bring healing, while sharp words poke like a sword.","age":"7-9","tags":["calm-self-control"]},{"id":"proverbs-15-1","ref":"Proverbs 15:1","kjv":"A soft answer turneth away wrath: but grievous words stir up anger.","say":"I give a soft, gentle answer, and the anger calms down.","theme":"calm-self-control","when":"when an argument is starting","mean":"Answering softly and kindly turns anger away instead of stirring it up.","age":"all","tags":["calm-self-control","friends-family"]},{"id":"proverbs-15-18","ref":"Proverbs 15:18","kjv":"A wrathful man stirreth up strife: but he that is slow to anger appeaseth strife.","say":"I am slow to get angry, and that helps calm the fight down.","theme":"calm-self-control","when":"when a fight is starting","mean":"Being slow to anger settles a quarrel instead of making it worse.","age":"all","tags":["calm-self-control"]},{"id":"proverbs-16-32","ref":"Proverbs 16:32","kjv":"He that is slow to anger is better than the mighty; and he that ruleth his spirit than he that taketh a city.","say":"When I stay calm instead of getting angry, God says I am strong on the inside.","theme":"calm-self-control","when":"when I feel angry","mean":"Ruling my own temper is better and stronger than a mighty soldier capturing a city.","age":"7-9","tags":["calm-self-control"]},{"id":"proverbs-19-11","ref":"Proverbs 19:11","kjv":"The discretion of a man deferreth his anger; and it is his glory to pass over a transgression.","say":"I can let a little thing go and not get angry.","theme":"calm-self-control","when":"when someone bothered me","mean":"It is wise and honorable to overlook a small wrong instead of getting upset.","age":"all","tags":["calm-self-control","wise-learner"]},{"id":"proverbs-21-23","ref":"Proverbs 21:23","kjv":"Whoso keepeth his mouth and his tongue keepeth his soul from troubles.","say":"I watch my mouth and my words, and that keeps me out of trouble.","theme":"calm-self-control","when":"when I want to stay out of trouble","mean":"Being careful with what I say keeps me safe from a lot of trouble.","age":"all","tags":["calm-self-control"]},{"id":"proverbs-29-11","ref":"Proverbs 29:11","kjv":"A fool uttereth all his mind: but a wise man keepeth it in till afterwards.","say":"I am wise, so I hold my words in instead of blurting everything out.","theme":"calm-self-control","when":"when I want to blurt something out","mean":"A wise person waits and thinks instead of saying every angry thing at once.","age":"7-9","tags":["calm-self-control"]},{"id":"psalms-141-3","ref":"Psalms 141:3","kjv":"Set a watch, O LORD, before my mouth; keep the door of my lips.","say":"Lord, please guard my mouth and help me watch what I say.","theme":"calm-self-control","when":"when I'm about to say something mean","mean":"I can ask God to guard my mouth and stop unkind words before they come out.","age":"all","tags":["calm-self-control"]},{"id":"psalms-34-13","ref":"Psalms 34:13","kjv":"Keep thy tongue from evil, and thy lips from speaking guile.","say":"I keep my tongue from mean words and from saying things that are not true.","theme":"calm-self-control","when":"when tempted to say mean or untrue words","mean":"I choose not to say evil words or tricky, untrue things ('guile' means deceit).","age":"all","tags":["calm-self-control"]},{"id":"1-corinthians-10-13","ref":"1 Corinthians 10:13","kjv":"There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able; but will with the temptation also make a way to escape, that ye may be able to bear it.","say":"When I am tempted to do wrong, God always makes a way out for me.","theme":"do-right","when":"being tempted","mean":"God always makes a way for me to say no to doing wrong.","age":"7-9","tags":["do-right"]},{"id":"1-peter-3-11","ref":"1 Peter 3:11","kjv":"Let him eschew evil, and do good; let him seek peace, and ensue it.","say":"I turn away from what is wrong, I do good, and I go after peace.","theme":"do-right","when":"making peace","mean":"I say no to bad, do what is good, and try to keep the peace.","age":"7-9","tags":["do-right"]},{"id":"1-thessalonians-5-15","ref":"1 Thessalonians 5:15","kjv":"See that none render evil for evil unto any man; but ever follow that which is good, both among yourselves, and to all men.","say":"When someone is mean to me, I don't pay back mean for mean. I choose to do good.","theme":"do-right","when":"someone was mean to me","mean":"Instead of getting even, I choose to do what is good.","age":"all","tags":["do-right","friends-family"]},{"id":"3-john-1-11","ref":"3 John 1:11","kjv":"Beloved, follow not that which is evil, but that which is good. He that doeth good is of God: but he that doeth evil hath not seen God.","say":"I don't copy bad things — I follow what is good.","theme":"do-right","when":"when friends are doing something wrong","mean":"God tells me to follow what is good, not what is bad, because doing good shows I belong to Him.","age":"7-9","tags":["do-right"]},{"id":"amos-5-15","ref":"Amos 5:15","kjv":"Hate the evil, and love the good, and establish judgment in the gate: it may be that the LORD God of hosts will be gracious unto the remnant of Joseph.","say":"I hate what is bad and I love what is good.","theme":"do-right","when":"sorting right from wrong","mean":"I say no to bad things and yes to good things.","age":"7-9","tags":["do-right"]},{"id":"daniel-1-8","ref":"Daniel 1:8","kjv":"But Daniel purposed in his heart that he would not defile himself with the portion of the king’s meat, nor with the wine which he drank: therefore he requested of the prince of the eunuchs that he might not defile himself.","say":"Like Daniel, I decide in my heart to do what is right.","theme":"do-right","when":"deciding ahead of time to do right","mean":"I make up my mind to do good before any trouble even comes.","age":"7-9","tags":["do-right"]},{"id":"ephesians-6-1","ref":"Ephesians 6:1","kjv":"Children, obey your parents in the Lord: for this is right.","say":"I obey my mum and dad, because it is the right thing to do.","theme":"do-right","when":"being told to do something by a parent","mean":"God says listening to my parents is the right way to live.","age":"all","tags":["do-right","friends-family"]},{"id":"exodus-20-12","ref":"Exodus 20:12","kjv":"Honour thy father and thy mother: that thy days may be long upon the land which the LORD thy God giveth thee.","say":"I honour my father and my mother.","theme":"do-right","when":"respecting parents","mean":"God asks me to treat my mum and dad with love and respect.","age":"all","tags":["do-right","friends-family"]},{"id":"ezekiel-36-27","ref":"Ezekiel 36:27","kjv":"And I will put my spirit within you, and cause you to walk in my statutes, and ye shall keep my judgments, and do them.","say":"God put His Spirit inside me to help me do what is right.","theme":"do-right","when":"tempted to do wrong","mean":"God's Spirit inside me helps me choose and do the good thing.","age":"all","tags":["do-right"]},{"id":"galatians-6-9","ref":"Galatians 6:9","kjv":"And let us not be weary in well doing: for in due season we shall reap, if we faint not.","say":"I keep doing good, and I will not get tired, because God sees me.","theme":"do-right","when":"when it is hard to keep being good","mean":"Even when it's hard, I keep doing good, trusting God's good reward in time.","age":"7-9","tags":["do-right","wise-learner"]},{"id":"genesis-39-9","ref":"Genesis 39:9","kjv":"There is none greater in this house than I; neither hath he kept back any thing from me but thee, because thou art his wife: how then can I do this great wickedness, and sin against God?","say":"I say no to wrong, because I don't want to sin against God.","theme":"do-right","when":"tempted to do wrong when no one is watching","mean":"Like Joseph, I say no to wrong because I love God.","age":"7-9","tags":["do-right"]},{"id":"joshua-24-15","ref":"Joshua 24:15","kjv":"And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD.","say":"Today I choose to serve the LORD.","theme":"do-right","when":"choosing who to follow","mean":"Every day I get to choose to follow God.","age":"all","tags":["do-right","friends-family"]},{"id":"matthew-5-8","ref":"Matthew 5:8","kjv":"Blessed are the pure in heart: for they shall see God.","say":"I keep my heart pure, and one day I will see God.","theme":"do-right","when":"keeping my heart pure","mean":"A clean heart is a happy heart, and it brings me close to God.","age":"all","tags":["do-right"]},{"id":"proverbs-12-22","ref":"Proverbs 12:22","kjv":"Lying lips are abomination to the LORD: but they that deal truly are his delight.","say":"I tell the truth, and that makes God glad.","theme":"do-right","when":"tempted to tell a lie","mean":"God is happy when I am honest.","age":"all","tags":["do-right"]},{"id":"proverbs-20-11","ref":"Proverbs 20:11","kjv":"Even a child is known by his doings, whether his work be pure, and whether it be right.","say":"Even though I am little, what I do can be pure and right.","theme":"do-right","when":"feeling too small to matter","mean":"My actions show who I am, even though I am still a child.","age":"7-9","tags":["do-right"]},{"id":"proverbs-4-23","ref":"Proverbs 4:23","kjv":"Keep thy heart with all diligence; for out of it are the issues of life.","say":"I guard my heart with care, because all I do comes from it.","theme":"do-right","when":"protecting my heart","mean":"I watch over my heart, because what is inside me shows in what I do.","age":"7-9","tags":["do-right"]},{"id":"psalm-24-4","ref":"Psalms 24:4","kjv":"He that hath clean hands, and a pure heart; who hath not lifted up his soul unto vanity, nor sworn deceitfully.","say":"With God's help, I keep clean hands and a pure heart.","theme":"do-right","when":"heart check","mean":"I try to do what is right, and I keep my heart clean on the inside.","age":"7-9","tags":["do-right"]},{"id":"psalm-34-14","ref":"Psalms 34:14","kjv":"Depart from evil, and do good; seek peace, and pursue it.","say":"I turn away from what is bad, and I do good.","theme":"do-right","when":"choosing good","mean":"I walk away from what is wrong and go after what is good.","age":"all","tags":["do-right","friends-family"]},{"id":"psalm-51-10","ref":"Psalms 51:10","kjv":"Create in me a clean heart, O God; and renew a right spirit within me.","say":"God, create in me a clean heart and make my spirit right.","theme":"do-right","when":"after I have done something wrong","mean":"When I mess up, I ask God to make my heart fresh and new again.","age":"all","tags":["do-right"]},{"id":"1-john-1-9","ref":"1 John 1:9","kjv":"If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness.","say":"When I tell God I am sorry for what I did wrong, He forgives me and makes me clean inside.","theme":"faith-prayer","when":"saying sorry","mean":"When you tell God the wrong things you did, He always forgives you and washes your heart clean.","age":"all","tags":["faith-prayer"]},{"id":"1-john-5-14","ref":"1 John 5:14","kjv":"And this is the confidence that we have in him, that, if we ask any thing according to his will, he heareth us:","say":"I am sure God hears me when I pray.","theme":"faith-prayer","when":"praying","mean":"I can be confident that God listens whenever I talk to Him.","age":"7-9","tags":["faith-prayer"]},{"id":"daniel-6-10","ref":"Daniel 6:10","kjv":"Now when Daniel knew that the writing was signed, he went into his house; and his windows being open in his chamber toward Jerusalem, he kneeled upon his knees three times a day, and prayed, and gave thanks before his God, as he did aforetime.","say":"Like Daniel, I kneel to pray and thank God every day.","theme":"faith-prayer","when":"being brave","mean":"Daniel kept praying and thanking God every day, and I can pray bravely too.","age":"7-9","tags":["faith-prayer"]},{"id":"hebrews-11-6","ref":"Hebrews 11:6","kjv":"But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him.","say":"When I believe in God and seek Him, it makes Him happy.","theme":"faith-prayer","when":"identity","mean":"Believing God is real and looking for Him pleases Him.","age":"7-9","tags":["faith-prayer"]},{"id":"mark-11-24","ref":"Mark 11:24","kjv":"Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them.","say":"When I pray, I believe, and I trust that God hears me.","theme":"faith-prayer","when":"praying","mean":"When I pray, I can believe and trust God with the things I ask Him for.","age":"7-9","tags":["faith-prayer"]},{"id":"mark-9-24","ref":"Mark 9:24","kjv":"And straightway the father of the child cried out, and said with tears, Lord, I believe; help thou mine unbelief.","say":"I believe in God, and when believing is hard, I ask Him to help me believe.","theme":"faith-prayer","when":"doubting","mean":"It is okay to tell God my faith feels weak and ask Him to help it grow.","age":"7-9","tags":["faith-prayer"]},{"id":"matthew-17-20","ref":"Matthew 17:20","kjv":"And Jesus said unto them, Because of your unbelief: for verily I say unto you, If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence to yonder place; and it shall remove; and nothing shall be impossible unto you.","say":"Even when my faith feels small like a seed, God is big, and that is enough.","theme":"faith-prayer","when":"feeling small","mean":"Even faith as tiny as a seed is powerful, because God is so big.","age":"7-9","tags":["faith-prayer"]},{"id":"matthew-21-22","ref":"Matthew 21:22","kjv":"And all things, whatsoever ye shall ask in prayer, believing, ye shall receive.","say":"When I pray, I believe that God hears me.","theme":"faith-prayer","when":"asking","mean":"When I pray and believe, I can trust that God hears me and cares about what I bring to Him.","age":"4-6","tags":["faith-prayer"]},{"id":"matthew-7-7","ref":"Matthew 7:7","kjv":"Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you:","say":"I ask, and God gives. I seek, and I find. I knock, and He opens the door.","theme":"faith-prayer","when":"asking","mean":"Jesus promises that when I keep asking, looking, and knocking, God answers me.","age":"4-6","tags":["faith-prayer"]},{"id":"philippians-4-6","ref":"Philippians 4:6","kjv":"Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God.","say":"I don't need to worry about anything; I can tell God everything and thank Him.","theme":"faith-prayer","when":"worried","mean":"Instead of worrying, I can pray about everything and thank God.","age":"7-9","tags":["faith-prayer"]},{"id":"psalm-34-4","ref":"Psalms 34:4","kjv":"I sought the LORD, and he heard me, and delivered me from all my fears.","say":"When I pray, God hears me and takes my fears away.","theme":"faith-prayer","when":"afraid","mean":"When I seek God, He hears me and frees me from fear.","age":"all","tags":["faith-prayer"]},{"id":"psalm-55-17","ref":"Psalms 55:17","kjv":"Evening, and morning, and at noon, will I pray, and cry aloud: and he shall hear my voice.","say":"Morning, noon, and night I pray, and God hears my voice.","theme":"faith-prayer","when":"any time of day","mean":"I can talk to God any time of the day, and He always hears me.","age":"4-6","tags":["faith-prayer"]},{"id":"psalm-56-3","ref":"Psalms 56:3","kjv":"What time I am afraid, I will trust in thee.","say":"When I feel afraid, I choose to trust God.","theme":"faith-prayer","when":"afraid","mean":"When scared feelings come, I can choose to trust God instead of staying afraid.","age":"4-6","tags":["faith-prayer"]},{"id":"psalm-62-8","ref":"Psalms 62:8","kjv":"Trust in him at all times; ye people, pour out your heart before him: God is a refuge for us. Selah.","say":"I can pour out my whole heart to God any time, because He is my safe place.","theme":"faith-prayer","when":"feeling sad","mean":"God is a safe place where I can pour out my feelings and trust Him.","age":"all","tags":["faith-prayer"]},{"id":"psalm-9-10","ref":"Psalms 9:10","kjv":"And they that know thy name will put their trust in thee: for thou, LORD, hast not forsaken them that seek thee.","say":"I know God's name, so I put my trust in Him; He never leaves me.","theme":"faith-prayer","when":"trust","mean":"Because I know God, I trust Him; He never leaves anyone who looks for Him.","age":"7-9","tags":["faith-prayer"]},{"id":"1-peter-2-24","ref":"1 Peter 2:24","kjv":"Who his own self bare our sins in his own body on the tree, that we, being dead to sins, should live unto righteousness: by whose stripes ye were healed.","say":"Jesus carried my sins on the cross, and by His stripes I am healed.","theme":"healthy-healed","when":"feeling sick","mean":"Because of what Jesus suffered for us on the cross, we are healed.","age":"7-9","tags":["healthy-healed"]},{"id":"exodus-15-26","ref":"Exodus 15:26","kjv":"And said, If thou wilt diligently hearken to the voice of the LORD thy God, and wilt do that which is right in his sight, and wilt give ear to his commandments, and keep all his statutes, I will put none of these diseases upon thee, which I have brought upon the Egyptians: for I am the LORD that healeth thee.","say":"God is the LORD who heals me.","theme":"healthy-healed","when":"when I am unwell","mean":"God calls Himself the One who heals you.","age":"all","tags":["healthy-healed"]},{"id":"isaiah-53-5","ref":"Isaiah 53:5","kjv":"But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.","say":"Jesus was wounded for me, and by His stripes I am healed and made well.","theme":"healthy-healed","when":"sick or hurting","mean":"Jesus took our hurts on the cross so that we can be healed and well.","age":"all","tags":["healthy-healed"]},{"id":"james-5-15","ref":"James 5:15","kjv":"And the prayer of faith shall save the sick, and the Lord shall raise him up; and if he have committed sins, they shall be forgiven him.","say":"When people pray for me, the Lord hears and lifts me up.","theme":"healthy-healed","when":"prayed for when sick","mean":"The prayer of faith helps the sick, and the Lord raises them up.","age":"7-9","tags":["healthy-healed"]},{"id":"jeremiah-30-17","ref":"Jeremiah 30:17","kjv":"For I will restore health unto thee, and I will heal thee of thy wounds, saith the LORD; because they called thee an Outcast, saying, This is Zion, whom no man seeketh after.","say":"God restores my health and heals my hurts.","theme":"healthy-healed","when":"getting better","mean":"God brings back our health and heals our wounds.","age":"all","tags":["healthy-healed"]},{"id":"malachi-4-2","ref":"Malachi 4:2","kjv":"But unto you that fear my name shall the Sun of righteousness arise with healing in his wings; and ye shall go forth, and grow up as calves of the stall.","say":"God shines on me like warm sunshine with healing, and I grow up strong.","theme":"healthy-healed","when":"growing up","mean":"God brings healing like warm sunshine, and we grow up healthy and strong.","age":"7-9","tags":["healthy-healed"]},{"id":"mark-5-34","ref":"Mark 5:34","kjv":"And he said unto her, Daughter, thy faith hath made thee whole; go in peace, and be whole of thy plague.","say":"Because I trust Jesus, He makes me whole.","theme":"healthy-healed","when":"needing healing","mean":"Jesus told a woman that her faith in Him made her whole and well.","age":"all","tags":["healthy-healed"]},{"id":"matthew-8-17","ref":"Matthew 8:17","kjv":"That it might be fulfilled which was spoken by Esaias the prophet, saying, Himself took our infirmities, and bare our sicknesses.","say":"Jesus took my sicknesses and carried them away for me.","theme":"healthy-healed","when":"feeling sick","mean":"Jesus took our weaknesses and sicknesses upon Himself.","age":"all","tags":["healthy-healed"]},{"id":"proverbs-4-22","ref":"Proverbs 4:22","kjv":"For they are life unto those that find them, and health to all their flesh.","say":"God's words are life and health to my whole body.","theme":"healthy-healed","when":"Bible time","mean":"When we find and keep God's words, they bring life and health to us.","age":"7-9","tags":["healthy-healed"]},{"id":"psalm-103-3","ref":"Psalms 103:3","kjv":"Who forgiveth all thine iniquities; who healeth all thy diseases;","say":"God forgives all I do wrong and heals all my sicknesses.","theme":"healthy-healed","when":"thanking God","mean":"God forgives the wrong things we do and heals our sicknesses.","age":"4-6","tags":["healthy-healed"]},{"id":"psalm-147-3","ref":"Psalms 147:3","kjv":"He healeth the broken in heart, and bindeth up their wounds.","say":"When my heart is sad, God heals it.","theme":"healthy-healed","when":"feeling sad","mean":"God heals sad, broken hearts and gently bandages our hurts.","age":"4-6","tags":["healthy-healed"]},{"id":"psalm-91-16","ref":"Psalms 91:16","kjv":"With long life will I satisfy him, and shew him my salvation.","say":"God satisfies me with a long and happy life.","theme":"healthy-healed","when":"bedtime","mean":"God promises to satisfy us with a long, good life.","age":"7-9","tags":["healthy-healed"]},{"id":"1-peter-1-8","ref":"1 Peter 1:8","kjv":"Whom having not seen, ye love; in whom, though now ye see him not, yet believing, ye rejoice with joy unspeakable and full of glory:","say":"I love Jesus even though I can't see Him, and I am full of joy.","theme":"joyful-hope","when":"loving Jesus","mean":"I believe in Jesus I cannot see, and that fills me with joy too big for words.","age":"7-9","tags":["joyful-hope"]},{"id":"1-thessalonians-5-16","ref":"1 Thessalonians 5:16","kjv":"Rejoice evermore.","say":"I can rejoice always!","theme":"joyful-hope","when":"all the time","mean":"God wants me to be joyful every single day.","age":"4-6","tags":["joyful-hope"]},{"id":"colossians-1-27","ref":"Colossians 1:27","kjv":"To whom God would make known what is the riches of the glory of this mystery among the Gentiles; which is Christ in you, the hope of glory:","say":"Christ lives in me, and He is my happy hope.","theme":"joyful-hope","when":"feeling sad","mean":"Jesus living in me is my hope for all the good things God has promised.","age":"all","tags":["joyful-hope"]},{"id":"habakkuk-3-18","ref":"Habakkuk 3:18","kjv":"Yet I will rejoice in the LORD, I will joy in the God of my salvation.","say":"Even when things go wrong, I will rejoice in the Lord, my Saviour.","theme":"joyful-hope","when":"when things go wrong","mean":"Even on hard days I can still be glad in God, who saves me.","age":"7-9","tags":["joyful-hope"]},{"id":"john-15-11","ref":"John 15:11","kjv":"These things have I spoken unto you, that my joy might remain in you, and that your joy might be full.","say":"Jesus gives me His joy, and my joy is full.","theme":"joyful-hope","when":"wanting real joy","mean":"Jesus shares His own joy with me so I can be truly full of joy.","age":"7-9","tags":["joyful-hope"]},{"id":"lamentations-3-23","ref":"Lamentations 3:23","kjv":"They are new every morning: great is thy faithfulness.","say":"God's mercies are new every morning, so today is a fresh start.","theme":"joyful-hope","when":"a fresh start","mean":"Every new morning God gives you fresh mercy and a fresh start.","age":"all","tags":["joyful-hope"]},{"id":"nehemiah-8-10","ref":"Nehemiah 8:10","kjv":"Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the LORD is your strength.","say":"The joy of the LORD is my strength, so I am strong even when I feel weak.","theme":"joyful-hope","when":"feeling sad","mean":"When I feel weak or sad, God's joy fills me up and makes me strong.","age":"4-6","tags":["joyful-hope"]},{"id":"philippians-4-4","ref":"Philippians 4:4","kjv":"Rejoice in the Lord alway: and again I say, Rejoice.","say":"I rejoice in the Lord always - and again I say, I rejoice!","theme":"joyful-hope","when":"any time","mean":"I can be happy in Jesus no matter what is happening.","age":"all","tags":["joyful-hope"]},{"id":"proverbs-17-22","ref":"Proverbs 17:22","kjv":"A merry heart doeth good like a medicine: but a broken spirit drieth the bones.","say":"A happy heart is good for me, like good medicine.","theme":"joyful-hope","when":"feeling grumpy","mean":"A cheerful heart helps me on the inside, the way medicine helps my body.","age":"7-9","tags":["joyful-hope"]},{"id":"psalm-118-24","ref":"Psalms 118:24","kjv":"This is the day which the LORD hath made; we will rejoice and be glad in it.","say":"This is the day the LORD made, so I will be glad and rejoice in it!","theme":"joyful-hope","when":"starting a new day","mean":"Every day is a gift from God for me to be happy in.","age":"4-6","tags":["joyful-hope"]},{"id":"psalm-126-5","ref":"Psalms 126:5","kjv":"They that sow in tears shall reap in joy.","say":"Even when I cry now, God can turn my tears into joy.","theme":"joyful-hope","when":"after a hard or sad time","mean":"Hard, tearful times can become joyful times when I trust God.","age":"7-9","tags":["joyful-hope"]},{"id":"psalm-16-11","ref":"Psalms 16:11","kjv":"Thou wilt shew me the path of life: in thy presence is fulness of joy; at thy right hand there are pleasures for evermore.","say":"When I am close to God, my heart is full of joy.","theme":"joyful-hope","when":"prayer time","mean":"Being near to God fills me all the way up with joy.","age":"7-9","tags":["joyful-hope"]},{"id":"psalm-42-11","ref":"Psalms 42:11","kjv":"Why art thou cast down, O my soul? and why art thou disquieted within me? hope thou in God: for I shall yet praise him, who is the health of my countenance, and my God.","say":"When I feel sad, I put my hope in God, and I will praise Him.","theme":"joyful-hope","when":"feeling down or discouraged","mean":"Even when my heart is heavy, I can hope in God and praise Him, because He is my help.","age":"7-9","tags":["joyful-hope"]},{"id":"psalm-71-5","ref":"Psalms 71:5","kjv":"For thou art my hope, O Lord GOD: thou art my trust from my youth.","say":"God is my hope, and I trust Him, even though I am young.","theme":"joyful-hope","when":"being a kid and trusting God","mean":"God is my hope, and I can trust Him right now while I am still little.","age":"all","tags":["joyful-hope"]},{"id":"psalms-30-5","ref":"Psalms 30:5","kjv":"For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.","say":"In God's favour is life, and after my tears, joy comes in the morning.","theme":"joyful-hope","when":"feeling sad","mean":"Sadness does not last forever; God brings joy in the morning after the tears.","age":"all","tags":["joyful-hope"]},{"id":"psalms-32-1","ref":"Psalms 32:1","kjv":"Blessed is he whose transgression is forgiven, whose sin is covered.","say":"I am happy, because God forgives me and covers my sin.","theme":"joyful-hope","when":"joy","mean":"You can be really happy because God has forgiven you and covered your sin.","age":"all","tags":["joyful-hope"]},{"id":"romans-15-13","ref":"Romans 15:13","kjv":"Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost.","say":"God is my God of hope, and He fills me with joy and peace when I believe.","theme":"joyful-hope","when":"needing hope","mean":"When I trust God, He fills me with hope, joy, and peace.","age":"7-9","tags":["joyful-hope"]},{"id":"1-john-3-1","ref":"1 John 3:1","kjv":"Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not.","say":"God's love is so big that He calls me His very own child.","theme":"loved-by-god","when":"feeling unloved","mean":"The Father's love is so great that He names me His own son or daughter.","age":"4-6","tags":["loved-by-god"]},{"id":"1-john-4-19","ref":"1 John 4:19","kjv":"We love him, because he first loved us.","say":"I love God because He loved me first.","theme":"loved-by-god","when":"identity","mean":"God loved you before you ever loved Him.","age":"all","tags":["loved-by-god"]},{"id":"1-peter-5-7","ref":"1 Peter 5:7","kjv":"Casting all your care upon him; for he careth for you.","say":"I give all my worries to God, because He cares about me.","theme":"loved-by-god","when":"worried","mean":"God wants your worries because He truly cares about you.","age":"all","tags":["loved-by-god"]},{"id":"1-thessalonians-1-4","ref":"1 Thessalonians 1:4","kjv":"Knowing, brethren beloved, your election of God.","say":"God loves me and chose me.","theme":"loved-by-god","when":"feeling unloved","mean":"God loves you dearly and chose you to be His own.","age":"4-6","tags":["loved-by-god"]},{"id":"2-timothy-1-9","ref":"2 Timothy 1:9","kjv":"Who hath saved us, and called us with an holy calling, not according to our works, but according to his own purpose and grace, which was given us in Christ Jesus before the world began,","say":"God saved me and called me by His grace — because He loves me, not because of what I do.","theme":"loved-by-god","when":"feeling not good enough","mean":"God calls me out of His grace and love, not because I am good enough.","age":"7-9","tags":["loved-by-god"]},{"id":"deuteronomy-7-9","ref":"Deuteronomy 7:9","kjv":"Know therefore that the LORD thy God, he is God, the faithful God, which keepeth covenant and mercy with them that love him and keep his commandments to a thousand generations;","say":"God is faithful, and He always keeps His promises to me.","theme":"loved-by-god","when":"when promises get broken","mean":"God is the faithful God who keeps His covenant and mercy; He always keeps His word.","age":"7-9","tags":["loved-by-god"]},{"id":"ephesians-1-6","ref":"Ephesians 1:6","kjv":"To the praise of the glory of his grace, wherein he hath made us accepted in the beloved.","say":"God accepts me because I belong to Jesus, His beloved Son.","theme":"loved-by-god","when":"feeling rejected","mean":"Because of Jesus, God welcomes you and is glad you are His.","age":"7-9","tags":["loved-by-god"]},{"id":"galatians-2-20","ref":"Galatians 2:20","kjv":"I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me.","say":"Jesus loves me and gave Himself just for me.","theme":"loved-by-god","when":"identity","mean":"Jesus loves me and gave Himself for me, and now He lives in me.","age":"all","tags":["loved-by-god"]},{"id":"hosea-11-4","ref":"Hosea 11:4","kjv":"I drew them with cords of a man, with bands of love: and I was to them as they that take off the yoke on their jaws, and I laid meat unto them.","say":"God gently draws me close with ropes of love.","theme":"loved-by-god","when":"feeling pushed away","mean":"God pulls me near to Himself softly and kindly, with cords of love.","age":"7-9","tags":["loved-by-god"]},{"id":"isaiah-40-11","ref":"Isaiah 40:11","kjv":"He shall feed his flock like a shepherd: he shall gather the lambs with his arm, and carry them in his bosom, and shall gently lead those that are with young.","say":"I am God's little lamb, and He holds me close to His heart.","theme":"loved-by-god","when":"needing comfort / feeling small","mean":"God is a gentle shepherd who gathers me, carries me in His arms, and holds me close.","age":"4-6","tags":["loved-by-god"]},{"id":"isaiah-43-4","ref":"Isaiah 43:4","kjv":"Since thou wast precious in my sight, thou hast been honourable, and I have loved thee: therefore will I give men for thee, and people for thy life.","say":"I am precious and loved in God's sight.","theme":"loved-by-god","when":"feeling worthless","mean":"God says I am precious to Him and He loves me.","age":"all","tags":["loved-by-god"]},{"id":"isaiah-49-15","ref":"Isaiah 49:15","kjv":"Can a woman forget her sucking child, that she should not have compassion on the son of her womb? yea, they may forget, yet will I not forget thee.","say":"God will never, ever forget me.","theme":"loved-by-god","when":"feeling forgotten","mean":"Even if everyone else forgot me, God promises that He never will.","age":"all","tags":["loved-by-god"]},{"id":"jeremiah-31-3","ref":"Jeremiah 31:3","kjv":"The LORD hath appeared of old unto me, saying, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.","say":"God loves me with a love that never, ever ends.","theme":"loved-by-god","when":"feeling unloved","mean":"God says His love for me is everlasting and will never run out.","age":"all","tags":["loved-by-god"]},{"id":"john-15-9","ref":"John 15:9","kjv":"As the Father hath loved me, so have I loved you: continue ye in my love.","say":"Jesus loves me just as the Father loves Him.","theme":"loved-by-god","when":"feeling unloved","mean":"Jesus loves you with the same big love the Father has for Him.","age":"all","tags":["loved-by-god"]},{"id":"john-3-16","ref":"John 3:16","kjv":"For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.","say":"God loved me so much that He gave His Son Jesus for me.","theme":"loved-by-god","when":"bedtime","mean":"God loved me enough to give His only Son Jesus so I can live with Him forever.","age":"all","tags":["loved-by-god"]},{"id":"luke-12-32","ref":"Luke 12:32","kjv":"Fear not, little flock; for it is your Father’s good pleasure to give you the kingdom.","say":"I will not be afraid, because God is my happy Father who delights to give me good gifts.","theme":"loved-by-god","when":"feeling afraid","mean":"God is my happy Father who is glad to give good gifts to His children.","age":"4-6","tags":["loved-by-god"]},{"id":"psalm-103-13","ref":"Psalms 103:13","kjv":"Like as a father pitieth his children, so the LORD pitieth them that fear him.","say":"God is tender to me, the way a kind daddy loves his child.","theme":"loved-by-god","when":"feeling alone","mean":"God is gentle and full of compassion toward me, like a loving father with his children.","age":"4-6","tags":["loved-by-god"]},{"id":"revelation-1-5","ref":"Revelation 1:5","kjv":"And from Jesus Christ, who is the faithful witness, and the first begotten of the dead, and the prince of the kings of the earth. Unto him that loved us, and washed us from our sins in his own blood,","say":"Jesus loves me, and He washed my sins away in His own blood.","theme":"loved-by-god","when":"feeling unloved","mean":"Jesus loves you so much that He washed all your sins away.","age":"all","tags":["loved-by-god"]},{"id":"romans-5-8","ref":"Romans 5:8","kjv":"But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us.","say":"Jesus died for me because God loves me, even when I do wrong.","theme":"loved-by-god","when":"feeling guilty","mean":"God loved you and sent Jesus even before you were good.","age":"7-9","tags":["loved-by-god"]},{"id":"romans-8-39","ref":"Romans 8:39","kjv":"Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord.","say":"Nothing in the whole world can ever separate me from God's love.","theme":"loved-by-god","when":"afraid","mean":"Nothing anywhere in all creation can pull God's love, which is in Christ Jesus, away from me.","age":"7-9","tags":["loved-by-god"]},{"id":"zephaniah-3-17","ref":"Zephaniah 3:17","kjv":"The LORD thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing.","say":"God is right here with me, and He sings happy songs because He loves me.","theme":"loved-by-god","when":"feeling sad","mean":"God is right here with me, loves me, and even sings over me because He is glad I am His.","age":"4-6","tags":["loved-by-god"]},{"id":"deuteronomy-31-6","ref":"Deuteronomy 31:6","kjv":"Be strong and of a good courage, fear not, nor be afraid of them: for the LORD thy God, he it is that doth go with thee; he will not fail thee, nor forsake thee.","say":"I am brave and not afraid, because God goes with me and never leaves me.","theme":"never-alone","when":"feeling alone","mean":"God never leaves me and never gives up on me, so I don't have to be afraid.","age":"all","tags":["never-alone"]},{"id":"deuteronomy-31-8","ref":"Deuteronomy 31:8","kjv":"And the LORD, he it is that doth go before thee; he will be with thee, he will not fail thee, neither forsake thee: fear not, neither be dismayed.","say":"I am not afraid, because God goes ahead of me and stays with me.","theme":"never-alone","when":"something new","mean":"God goes ahead of me into everything, so I can follow Him without fear.","age":"all","tags":["never-alone"]},{"id":"genesis-28-15","ref":"Genesis 28:15","kjv":"And, behold, I am with thee, and will keep thee in all places whither thou goest, and will bring thee again into this land; for I will not leave thee, until I have done that which I have spoken to thee of.","say":"Wherever I go, God is with me and keeps me safe.","theme":"never-alone","when":"new places","mean":"God stays with me and watches over me everywhere I go.","age":"all","tags":["never-alone"]},{"id":"haggai-2-5","ref":"Haggai 2:5","kjv":"According to the word that I covenanted with you when ye came out of Egypt, so my spirit remaineth among you: fear ye not.","say":"God's Spirit stays with me, so I do not need to be afraid.","theme":"never-alone","when":"afraid","mean":"God's Spirit stays close to me, so I do not need to be afraid.","age":"all","tags":["never-alone"]},{"id":"hebrews-13-5","ref":"Hebrews 13:5","kjv":"Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.","say":"I am happy with what I have, because God will never leave me.","theme":"never-alone","when":"feeling alone","mean":"God promised, 'I will never leave you,' so I never have to feel alone.","age":"all","tags":["never-alone"]},{"id":"isaiah-41-13","ref":"Isaiah 41:13","kjv":"For I the LORD thy God will hold thy right hand, saying unto thee, Fear not; I will help thee.","say":"God holds my right hand and says, 'Do not be afraid.'","theme":"never-alone","when":"worried","mean":"God takes my hand like a loving Father and tells me not to be afraid.","age":"4-6","tags":["never-alone"]},{"id":"isaiah-43-2","ref":"Isaiah 43:2","kjv":"When thou passest through the waters, I will be with thee; and through the rivers, they shall not overflow thee: when thou walkest through the fire, thou shalt not be burned; neither shall the flame kindle upon thee.","say":"Even in deep waters or scary times, God is with me.","theme":"never-alone","when":"scary situations","mean":"Even in deep water or hard times, God stays with me and keeps me safe.","age":"7-9","tags":["never-alone"]},{"id":"isaiah-44-2","ref":"Isaiah 44:2","kjv":"Thus saith the LORD that made thee, and formed thee from the womb, which will help thee; Fear not, O Jacob, my servant; and thou, Jesurun, whom I have chosen.","say":"God made me and formed me, and He promises to help me, so I will not be afraid.","theme":"never-alone","when":"afraid","mean":"The God who made me promises to help me, so I don't need to be afraid.","age":"all","tags":["never-alone"]},{"id":"isaiah-49-16","ref":"Isaiah 49:16","kjv":"Behold, I have graven thee upon the palms of my hands; thy walls are continually before me.","say":"God never forgets me, because He has written my name on His hands.","theme":"never-alone","when":"feeling forgotten","mean":"God has engraved me on His hands and always remembers me.","age":"4-6","tags":["never-alone"]},{"id":"jeremiah-1-8","ref":"Jeremiah 1:8","kjv":"Be not afraid of their faces: for I am with thee to deliver thee, saith the LORD.","say":"I will not be afraid of people, because God is with me to help me.","theme":"never-alone","when":"being teased","mean":"God tells me not to fear people, because He is with me to help me.","age":"7-9","tags":["never-alone"]},{"id":"john-14-17","ref":"John 14:17","kjv":"Even the Spirit of truth; whom the world cannot receive, because it seeth him not, neither knoweth him: but ye know him; for he dwelleth with you, and shall be in you.","say":"God's Spirit of truth stays with me and lives in me.","theme":"never-alone","when":"bedtime","mean":"The Holy Spirit stays right beside you and lives inside you.","age":"all","tags":["never-alone"]},{"id":"john-14-23","ref":"John 14:23","kjv":"Jesus answered and said unto him, If a man love me, he will keep my words: and my Father will love him, and we will come unto him, and make our abode with him.","say":"When I love Jesus, He and the Father come and make their home with me.","theme":"never-alone","when":"feeling alone","mean":"When I love Jesus and keep His words, God comes and makes His home with me, so I am never alone.","age":"7-9","tags":["never-alone"]},{"id":"matthew-1-23","ref":"Matthew 1:23","kjv":"Behold, a virgin shall be with child, and shall bring forth a son, and they shall call his name Emmanuel, which being interpreted is, God with us.","say":"Jesus is Emmanuel, which means God is with me.","theme":"never-alone","when":"identity","mean":"Jesus' name Emmanuel means 'God with us,' so God is truly with me.","age":"all","tags":["never-alone"]},{"id":"matthew-10-29","ref":"Matthew 10:29","kjv":"Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father.","say":"Not even a little sparrow falls without my Father, and He is watching over me.","theme":"never-alone","when":"feeling unnoticed or small","mean":"God sees every tiny bird, so I know He sees me and never overlooks me.","age":"7-9","tags":["never-alone"]},{"id":"matthew-28-20","ref":"Matthew 28:20","kjv":"Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.","say":"Jesus is with me always, every single day.","theme":"never-alone","when":"every day","mean":"Jesus promised to be with us every day, always, to the very end.","age":"all","tags":["never-alone"]},{"id":"psalm-139-10","ref":"Psalms 139:10","kjv":"Even there shall thy hand lead me, and thy right hand shall hold me.","say":"Everywhere I go, God's hand leads me and holds me.","theme":"never-alone","when":"far from home","mean":"No matter how far I go, God's hand still leads me and holds me.","age":"all","tags":["never-alone"]},{"id":"psalm-145-18","ref":"Psalms 145:18","kjv":"The LORD is nigh unto all them that call upon him, to all that call upon him in truth.","say":"God comes near to me whenever I call on Him.","theme":"never-alone","when":"feeling alone","mean":"God draws close to everyone who calls to Him honestly, so I am never truly alone.","age":"4-6","tags":["never-alone"]},{"id":"psalm-27-10","ref":"Psalms 27:10","kjv":"When my father and my mother forsake me, then the LORD will take me up.","say":"Even if everyone else leaves, the Lord will take care of me.","theme":"never-alone","when":"feeling left out or abandoned","mean":"Even if people let me down, God will always pick me up and take care of me.","age":"7-9","tags":["never-alone"]},{"id":"psalm-34-18","ref":"Psalms 34:18","kjv":"The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.","say":"When I am sad, God is close to me.","theme":"never-alone","when":"feeling sad","mean":"When my heart hurts, God comes near to comfort me.","age":"all","tags":["never-alone"]},{"id":"psalm-73-23","ref":"Psalms 73:23","kjv":"Nevertheless I am continually with thee: thou hast holden me by my right hand.","say":"I am always with God, and He holds my hand.","theme":"never-alone","when":"feeling alone","mean":"God keeps me close to Him all the time and holds my hand.","age":"4-6","tags":["never-alone"]},{"id":"psalms-139-7","ref":"Psalms 139:7","kjv":"Whither shall I go from thy spirit? or whither shall I flee from thy presence?","say":"God's Spirit is with me everywhere I go.","theme":"never-alone","when":"scared of the dark","mean":"There is nowhere I can go that God's Spirit and presence are not already with me.","age":"all","tags":["never-alone"]},{"id":"zechariah-2-10","ref":"Zechariah 2:10","kjv":"Sing and rejoice, O daughter of Zion: for, lo, I come, and I will dwell in the midst of thee, saith the LORD.","say":"God comes to live right in the middle of His people, so I can sing for joy.","theme":"never-alone","when":"feeling alone","mean":"God promised to come and live among His people, so we are not alone and we can be glad.","age":"7-9","tags":["never-alone"]},{"id":"2-thessalonians-3-16","ref":"2 Thessalonians 3:16","kjv":"Now the Lord of peace himself give you peace always by all means. The Lord be with you all.","say":"The Lord of peace gives me His peace all the time, in every way.","theme":"peaceful-rest","when":"needing peace","mean":"Jesus is the Lord of peace, and He gives me peace always, no matter what.","age":"7-9","tags":["peaceful-rest"]},{"id":"colossians-3-15","ref":"Colossians 3:15","kjv":"And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful.","say":"I let God's peace be the boss of my heart, and I stay thankful.","theme":"peaceful-rest","when":"upset","mean":"I can let God's peace be in charge of my heart instead of my worries.","age":"7-9","tags":["peaceful-rest"]},{"id":"exodus-33-14","ref":"Exodus 33:14","kjv":"And he said, My presence shall go with thee, and I will give thee rest.","say":"God's presence goes with me, and He gives me rest.","theme":"peaceful-rest","when":"bedtime","mean":"God goes with me and gives my heart rest, even at night.","age":"4-6","tags":["peaceful-rest"]},{"id":"isaiah-26-3","ref":"Isaiah 26:3","kjv":"Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.","say":"God keeps me in perfect peace when I keep my mind on Him and trust Him.","theme":"peaceful-rest","when":"anxious","mean":"When I keep thinking about God and trusting Him, He gives me a calm, perfect peace.","age":"all","tags":["peaceful-rest"]},{"id":"john-14-27","ref":"John 14:27","kjv":"Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.","say":"Jesus gives me His own peace, so my heart is not troubled or afraid.","theme":"peaceful-rest","when":"worried or anxious","mean":"Jesus gives me a special peace so my heart does not have to be troubled or scared.","age":"all","tags":["peaceful-rest"]},{"id":"matthew-11-28","ref":"Matthew 11:28","kjv":"Come unto me, all ye that labour and are heavy laden, and I will give you rest.","say":"When I feel tired and heavy inside, I come to Jesus, and He gives me rest.","theme":"peaceful-rest","when":"overwhelmed","mean":"When life feels too heavy, I can come to Jesus and He gives me rest.","age":"all","tags":["peaceful-rest"]},{"id":"matthew-6-34","ref":"Matthew 6:34","kjv":"Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.","say":"I won't worry about tomorrow, because my Father in heaven takes care of me.","theme":"peaceful-rest","when":"worried about tomorrow","mean":"I don't need to worry about tomorrow; I can trust God for one day at a time.","age":"7-9","tags":["peaceful-rest"]},{"id":"numbers-6-26","ref":"Numbers 6:26","kjv":"The LORD lift up his countenance upon thee, and give thee peace.","say":"God looks at me with love and gives me His peace.","theme":"peaceful-rest","when":"needing comfort","mean":"God smiles on me with love and gives me His peace.","age":"all","tags":["peaceful-rest"]},{"id":"philippians-4-7","ref":"Philippians 4:7","kjv":"And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.","say":"God's peace guards my heart and my mind through Jesus.","theme":"peaceful-rest","when":"a worried heart","mean":"God gives a peace so big it guards my heart and thoughts, through Jesus.","age":"all","tags":["peaceful-rest"]},{"id":"proverbs-1-33","ref":"Proverbs 1:33","kjv":"But whoso hearkeneth unto me shall dwell safely, and shall be quiet from fear of evil.","say":"When I listen to God, I am safe and my heart is quiet, not afraid.","theme":"peaceful-rest","when":"worried about bad things","mean":"Listening to God keeps me safe and calm instead of afraid.","age":"7-9","tags":["peaceful-rest"]},{"id":"psalm-29-11","ref":"Psalms 29:11","kjv":"The LORD will give strength unto his people; the LORD will bless his people with peace.","say":"God gives me strength and fills me with peace.","theme":"peaceful-rest","when":"bedtime","mean":"God makes me strong and gives me peace, so I can rest calm and safe.","age":"4-6","tags":["peaceful-rest"]},{"id":"psalms-23-2","ref":"Psalms 23:2","kjv":"He maketh me to lie down in green pastures: he leadeth me beside the still waters.","say":"My Shepherd gives me rest in green grass and leads me beside calm, still water.","theme":"peaceful-rest","when":"restless","mean":"God is my Shepherd who leads me to rest in quiet, peaceful places.","age":"all","tags":["peaceful-rest"]},{"id":"psalms-55-22","ref":"Psalms 55:22","kjv":"Cast thy burden upon the LORD, and he shall sustain thee: he shall never suffer the righteous to be moved.","say":"I give my heavy load to the Lord, and He holds me up.","theme":"peaceful-rest","when":"burdened","mean":"I can hand my heavy worries to the Lord, and He will hold me steady.","age":"7-9","tags":["peaceful-rest"]},{"id":"psalms-94-19","ref":"Psalms 94:19","kjv":"In the multitude of my thoughts within me thy comforts delight my soul.","say":"When my mind is full of worried thoughts, God's comfort makes me glad inside.","theme":"peaceful-rest","when":"racing thoughts","mean":"Even when lots of worried thoughts fill my mind, God comforts me and makes me happy inside.","age":"7-9","tags":["peaceful-rest"]},{"id":"2-thessalonians-3-3","ref":"2 Thessalonians 3:3","kjv":"But the Lord is faithful, who shall stablish you, and keep you from evil.","say":"God is faithful; He makes me strong and keeps me from evil.","theme":"protected-safe","when":"scared of bad things","mean":"God always keeps His promise to make me strong and keep me safe from what is bad.","age":"7-9","tags":["protected-safe"]},{"id":"deuteronomy-33-12","ref":"Deuteronomy 33:12","kjv":"And of Benjamin he said, The beloved of the LORD shall dwell in safety by him; and the Lord shall cover him all the day long, and he shall dwell between his shoulders.","say":"I am God's beloved, and He covers me and keeps me safe all day long.","theme":"protected-safe","when":"feeling unsafe","mean":"God loves me and stays right beside me, covering me the whole day.","age":"all","tags":["protected-safe"]},{"id":"isaiah-54-17","ref":"Isaiah 54:17","kjv":"No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.","say":"No unkind word or weapon against me will win, because God keeps me safe.","theme":"protected-safe","when":"being picked on","mean":"God protects me, so unkind words and things cannot beat me.","age":"7-9","tags":["protected-safe"]},{"id":"john-10-28","ref":"John 10:28","kjv":"And I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand.","say":"I am safe in Jesus' hand, and no one can ever take me away.","theme":"protected-safe","when":"feeling unsafe","mean":"Jesus holds me in His hand and gives me eternal life; no one can snatch me away from Him.","age":"all","tags":["protected-safe"]},{"id":"nahum-1-7","ref":"Nahum 1:7","kjv":"The LORD is good, a strong hold in the day of trouble; and he knoweth them that trust in him.","say":"On a hard day, God is my safe, strong place, and He knows me.","theme":"protected-safe","when":"a hard day","mean":"God is good and holds me safe on my hardest days because He knows and loves those who trust Him.","age":"7-9","tags":["protected-safe"]},{"id":"proverbs-18-10","ref":"Proverbs 18:10","kjv":"The name of the LORD is a strong tower: the righteous runneth into it, and is safe.","say":"I run to God, my strong tower, and I am safe.","theme":"protected-safe","when":"scared","mean":"When I am scared, I can run to God like hiding inside a strong castle, and He keeps me safe.","age":"4-6","tags":["protected-safe"]},{"id":"psalm-121-7","ref":"Psalms 121:7","kjv":"The LORD shall preserve thee from all evil: he shall preserve thy soul.","say":"God keeps me safe from harm and watches over all of me.","theme":"protected-safe","when":"going out","mean":"God protects me from harm and takes care of my whole self, inside and out.","age":"all","tags":["protected-safe"]},{"id":"psalm-28-7","ref":"Psalms 28:7","kjv":"The LORD is my strength and my shield; my heart trusted in him, and I am helped: therefore my heart greatly rejoiceth; and with my song will I praise him.","say":"The Lord is my strength and my shield, and my heart is glad in Him.","theme":"protected-safe","when":"needing help","mean":"God keeps me strong and safe, so my heart can be happy in Him.","age":"7-9","tags":["protected-safe"]},{"id":"psalm-32-7","ref":"Psalms 32:7","kjv":"Thou art my hiding place; thou shalt preserve me from trouble; thou shalt compass me about with songs of deliverance. Selah.","say":"God is my hiding place, and He keeps me safe from trouble.","theme":"protected-safe","when":"overwhelmed","mean":"When everything feels like too much, I can hide in God and He keeps me safe.","age":"all","tags":["protected-safe"]},{"id":"psalm-34-7","ref":"Psalms 34:7","kjv":"The angel of the LORD encampeth round about them that fear him, and delivereth them.","say":"God's angel camps all around me and keeps me safe.","theme":"protected-safe","when":"feeling alone","mean":"God's angel stays close around me to protect me and rescue me, so I am never really alone.","age":"4-6","tags":["protected-safe"]},{"id":"psalm-46-1","ref":"Psalms 46:1","kjv":"God is our refuge and strength, a very present help in trouble.","say":"God is my strong safe place, and He helps me right when I need Him.","theme":"protected-safe","when":"trouble","mean":"When things go wrong, God is a safe hiding place and He is always close by.","age":"all","tags":["protected-safe"]},{"id":"psalm-91-11","ref":"Psalms 91:11","kjv":"For he shall give his angels charge over thee, to keep thee in all thy ways.","say":"God sends His angels to watch over me wherever I go.","theme":"protected-safe","when":"going somewhere new","mean":"God tells His angels to take care of me all through my day.","age":"4-6","tags":["protected-safe"]},{"id":"psalm-91-13","ref":"Psalms 91:13","kjv":"Thou shalt tread upon the lion and adder: the young lion and the dragon shalt thou trample under feet.","say":"God keeps me safe, so even lions and snakes are under my feet.","theme":"protected-safe","when":"nightmares","mean":"God protects me, so even big scary things cannot harm me.","age":"4-6","tags":["protected-safe"]},{"id":"psalm-91-4","ref":"Psalms 91:4","kjv":"He shall cover thee with his feathers, and under his wings shalt thou trust: his truth shall be thy shield and buckler.","say":"God keeps me safe, covered under His wings.","theme":"protected-safe","when":"feeling small","mean":"God hides me close and safe, like a bird covers its babies with its wings.","age":"4-6","tags":["protected-safe"]},{"id":"psalms-17-8","ref":"Psalms 17:8","kjv":"Keep me as the apple of the eye, hide me under the shadow of thy wings,","say":"God keeps me as the apple of His eye and hides me safe under His wings.","theme":"protected-safe","when":"bedtime","mean":"God guards me as carefully as I guard my own eyes and shelters me close.","age":"all","tags":["protected-safe"]},{"id":"zechariah-2-8","ref":"Zechariah 2:8","kjv":"For thus saith the LORD of hosts; After the glory hath he sent me unto the nations which spoiled you: for he that toucheth you toucheth the apple of his eye.","say":"I am the apple of God's eye, and He watches over me.","theme":"protected-safe","when":"being bullied","mean":"You are so precious to God that anyone who hurts you is poking at His own eye, and He is watching.","age":"7-9","tags":["protected-safe"]},{"id":"deuteronomy-2-7","ref":"Deuteronomy 2:7","kjv":"For the LORD thy God hath blessed thee in all the works of thy hand: he knoweth thy walking through this great wilderness: these forty years the LORD thy God hath been with thee; thou hast lacked nothing.","say":"God is with me every step, and I will not lack any good thing.","theme":"provided-for","when":"a long or hard day","mean":"God knew every step His people took and they lacked nothing; He watches over my steps too.","age":"7-9","tags":["provided-for"]},{"id":"james-1-17","ref":"James 1:17","kjv":"Every good gift and every perfect gift is from above, and cometh down from the Father of lights, with whom is no variableness, neither shadow of turning.","say":"Every good thing I have is a gift from God who loves me.","theme":"provided-for","when":"feeling thankful / counting blessings","mean":"Every good thing in my life comes down from God, my good Father who never changes.","age":"7-9","tags":["provided-for"]},{"id":"matthew-6-11","ref":"Matthew 6:11","kjv":"Give us this day our daily bread.","say":"I ask God for my bread today, and He gives me what I need.","theme":"provided-for","when":"at mealtime or praying","mean":"Jesus taught me to ask God for what I need each day, and God loves to give it.","age":"4-6","tags":["provided-for"]},{"id":"matthew-6-26","ref":"Matthew 6:26","kjv":"Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?","say":"God feeds the little birds, and He loves me even more, so I don't need to worry.","theme":"provided-for","when":"worried about having enough","mean":"Birds do not store up food, but God still feeds them, and I am worth much more to Him than birds.","age":"4-6","tags":["provided-for"]},{"id":"matthew-6-28","ref":"Matthew 6:28","kjv":"And why take ye thought for raiment? Consider the lilies of the field, how they grow; they toil not, neither do they spin:","say":"God dresses the flowers in beauty, and He will clothe me too.","theme":"provided-for","when":"worried about clothes or feeling plain","mean":"Flowers do not work to make their pretty petals; God clothes them, and He cares about what I wear too.","age":"4-6","tags":["provided-for"]},{"id":"nehemiah-9-21","ref":"Nehemiah 9:21","kjv":"Yea, forty years didst thou sustain them in the wilderness, so that they lacked nothing; their clothes waxed not old, and their feet swelled not.","say":"God takes care of me, so I will never run out of what I need.","theme":"provided-for","when":"worried something will run out","mean":"God sustained His people forty years and they lacked nothing, and He still provides for me.","age":"7-9","tags":["provided-for"]},{"id":"philippians-4-19","ref":"Philippians 4:19","kjv":"But my God shall supply all your need according to his riches in glory by Christ Jesus.","say":"My God will supply everything I need.","theme":"provided-for","when":"when I need something","mean":"God is very rich in good things, and He gives His children what they truly need.","age":"7-9","tags":["provided-for"]},{"id":"psalm-145-16","ref":"Psalms 145:16","kjv":"Thou openest thine hand, and satisfiest the desire of every living thing.","say":"God opens His hand and gives me what I need.","theme":"provided-for","when":"mealtime / feeling hungry","mean":"God feeds every living thing, and He gladly gives good things to me too.","age":"4-6","tags":["provided-for"]},{"id":"psalm-147-9","ref":"Psalms 147:9","kjv":"He giveth to the beast his food, and to the young ravens which cry.","say":"God hears the baby birds when they cry, and He feeds them — and He feeds me too.","theme":"provided-for","when":"hungry / crying for help","mean":"If God feeds the little birds when they cry, I can trust Him to take care of me.","age":"4-6","tags":["provided-for"]},{"id":"psalm-34-10","ref":"Psalms 34:10","kjv":"The young lions do lack, and suffer hunger: but they that seek the LORD shall not want any good thing.","say":"When I look to God, I will not go without any good thing.","theme":"provided-for","when":"wanting something / feeling left out","mean":"Even strong young lions get hungry, but those who seek the LORD will not lack any good thing.","age":"7-9","tags":["provided-for"]},{"id":"psalms-23-1","ref":"Psalms 23:1","kjv":"The LORD is my shepherd; I shall not want.","say":"The Lord is my shepherd, so I have everything I really need.","theme":"provided-for","when":"worried about having enough","mean":"God takes care of me the way a kind shepherd takes care of his little sheep.","age":"all","tags":["provided-for"]},{"id":"acts-12-6","ref":"Acts 12:6","kjv":"And when Herod would have brought him forth, the same night Peter was sleeping between two soldiers, bound with two chains: and the keepers before the door kept the prison.","say":"Even in a scary place, Peter slept in peace because God was with him, and God is with me too.","theme":"restful-sleep","when":"in trouble or worried","mean":"Peter slept soundly even in prison, trusting God to care for him.","age":"7-9","tags":["restful-sleep"]},{"id":"ezekiel-34-25","ref":"Ezekiel 34:25","kjv":"And I will make with them a covenant of peace, and will cause the evil beasts to cease out of the land: and they shall dwell safely in the wilderness, and sleep in the woods.","say":"God's peace keeps me so safe that I could even sleep out in the woods.","theme":"restful-sleep","when":"sleeping somewhere new","mean":"God's covenant of peace means His people are safe to rest anywhere.","age":"7-9","tags":["restful-sleep"]},{"id":"hosea-2-18","ref":"Hosea 2:18","kjv":"And in that day will I make a covenant for them with the beasts of the field, and with the fowls of heaven, and with the creeping things of the ground: and I will break the bow and the sword and the battle out of the earth, and will make them to lie down safely.","say":"God makes me lie down in safety.","theme":"restful-sleep","when":"bedtime","mean":"God promises to make His people lie down safely, with no danger around.","age":"all","tags":["restful-sleep"]},{"id":"leviticus-26-6","ref":"Leviticus 26:6","kjv":"And I will give peace in the land, and ye shall lie down, and none shall make you afraid: and I will rid evil beasts out of the land, neither shall the sword go through your land.","say":"I lie down in peace, because God gives me peace.","theme":"restful-sleep","when":"afraid at bedtime","mean":"God gives peace so His people can lie down with nothing to be scared of.","age":"7-9","tags":["restful-sleep"]},{"id":"mark-4-38","ref":"Mark 4:38","kjv":"And he was in the hinder part of the ship, asleep on a pillow: and they awake him, and say unto him, Master, carest thou not that we perish?","say":"Jesus slept in peace right through the storm, and I can rest in Him too.","theme":"restful-sleep","when":"scared during a storm","mean":"Jesus rested calmly in the storm because He trusted the Father, and I can rest in Him.","age":"all","tags":["restful-sleep"]},{"id":"proverbs-3-24","ref":"Proverbs 3:24","kjv":"When thou liest down, thou shalt not be afraid: yea, thou shalt lie down, and thy sleep shall be sweet.","say":"When I lie down, I am not afraid, and my sleep is sweet.","theme":"restful-sleep","when":"bedtime","mean":"I can lie down without being scared, and God gives me sweet sleep.","age":"4-6","tags":["restful-sleep"]},{"id":"psalm-121-3","ref":"Psalms 121:3","kjv":"He will not suffer thy foot to be moved: he that keepeth thee will not slumber.","say":"The God who keeps me never falls asleep.","theme":"restful-sleep","when":"scared at night","mean":"God is awake and guarding me all night long, so nothing can sneak up on me.","age":"4-6","tags":["restful-sleep"]},{"id":"psalm-127-2","ref":"Psalms 127:2","kjv":"It is vain for you to rise up early, to sit up late, to eat the bread of sorrows: for so he giveth his beloved sleep.","say":"God loves me, and He gives me sleep as a gift.","theme":"restful-sleep","when":"can't fall asleep","mean":"I don't have to worry all night; sleep is a present God gives to the people He loves.","age":"all","tags":["restful-sleep"]},{"id":"psalm-3-5","ref":"Psalms 3:5","kjv":"I laid me down and slept; I awaked; for the LORD sustained me.","say":"I sleep and I wake up again, because God holds me up all night.","theme":"restful-sleep","when":"bedtime","mean":"I can sleep and wake up again because God holds me and keeps me all through the night.","age":"4-6","tags":["restful-sleep"]},{"id":"psalm-4-8","ref":"Psalms 4:8","kjv":"I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety.","say":"I lie down and sleep in peace, because God keeps me safe.","theme":"restful-sleep","when":"bedtime","mean":"I can sleep without worry because God watches over me and keeps me safe all night.","age":"all","tags":["restful-sleep"]},{"id":"psalm-91-5","ref":"Psalms 91:5","kjv":"Thou shalt not be afraid for the terror by night; nor for the arrow that flieth by day;","say":"I am not afraid of the night, because God is with me.","theme":"restful-sleep","when":"afraid of the dark","mean":"The dark and the night cannot scare me, because God is watching over me.","age":"4-6","tags":["restful-sleep"]},{"id":"zephaniah-3-13","ref":"Zephaniah 3:13","kjv":"The remnant of Israel shall not do iniquity, nor speak lies; neither shall a deceitful tongue be found in their mouth: for they shall feed and lie down, and none shall make them afraid.","say":"I lie down in peace, and no one can make me afraid.","theme":"restful-sleep","when":"afraid","mean":"God's people get to rest and lie down, and nothing can frighten them.","age":"all","tags":["restful-sleep"]},{"id":"1-john-3-18","ref":"1 John 3:18","kjv":"My little children, let us not love in word, neither in tongue; but in deed and in truth.","say":"I show love by what I do, not just by what I say.","theme":"shine-kind","when":"helping","mean":"Real love means doing kind things, not only saying nice words.","age":"7-9","tags":["shine-kind","friends-family"]},{"id":"1-timothy-4-12","ref":"1 Timothy 4:12","kjv":"Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity.","say":"Even though I am young, I can show others a good and pure way to live.","theme":"shine-kind","when":"feeling too little","mean":"I don't have to be grown-up to be an example of love and good living.","age":"7-9","tags":["shine-kind"]},{"id":"acts-20-35","ref":"Acts 20:35","kjv":"I have shewed you all things, how that so labouring ye ought to support the weak, and to remember the words of the Lord Jesus, how he said, It is more blessed to give than to receive.","say":"I love to give and share, because giving makes a happy, blessed heart.","theme":"shine-kind","when":"sharing","mean":"Jesus said it is more blessed to give than to receive, so sharing brings true joy.","age":"all","tags":["shine-kind","friends-family"]},{"id":"colossians-3-12","ref":"Colossians 3:12","kjv":"Put on therefore, as the elect of God, holy and beloved, bowels of mercies, kindness, humbleness of mind, meekness, longsuffering;","say":"God chose me and loves me, so I put on kindness like a warm coat.","theme":"shine-kind","when":"morning / getting dressed","mean":"Because God chose you and loves you, you can 'wear' kindness to everyone today.","age":"all","tags":["shine-kind"]},{"id":"colossians-4-6","ref":"Colossians 4:6","kjv":"Let your speech be alway with grace, seasoned with salt, that ye may know how ye ought to answer every man.","say":"My words are always kind and full of grace.","theme":"shine-kind","when":"how to answer","mean":"I speak with grace, so I know the kind way to answer anyone.","age":"7-9","tags":["shine-kind"]},{"id":"daniel-12-3","ref":"Daniel 12:3","kjv":"And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever.","say":"When I am wise and kind, I shine like a bright star for God.","theme":"shine-kind","when":"bedtime","mean":"Being wise and helping others makes me shine like a star for God.","age":"4-6","tags":["shine-kind"]},{"id":"ephesians-4-29","ref":"Ephesians 4:29","kjv":"Let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying, that it may minister grace unto the hearers.","say":"Only good, helpful words come out of my mouth, words that build others up.","theme":"shine-kind","when":"choosing my words","mean":"I speak words that help and build up the people who hear them.","age":"all","tags":["shine-kind"]},{"id":"ephesians-4-32","ref":"Ephesians 4:32","kjv":"And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ’s sake hath forgiven you.","say":"I am kind and gentle, and I forgive others, because God forgives me through Jesus.","theme":"shine-kind","when":"after a fight","mean":"I can be gentle and forgive my friends, just as God forgives me for Jesus' sake.","age":"all","tags":["shine-kind","friends-family"]},{"id":"ephesians-5-8","ref":"Ephesians 5:8","kjv":"For ye were sometimes darkness, but now are ye light in the Lord: walk as children of light:","say":"I am a child of light, and I walk in God's bright, loving way.","theme":"shine-kind","when":"identity","mean":"God made me light in the Lord, so I live in a bright and loving way.","age":"4-6","tags":["shine-kind"]},{"id":"galatians-5-22","ref":"Galatians 5:22","kjv":"But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,","say":"God's Spirit grows love, joy, peace, and kindness in me.","theme":"shine-kind","when":"wanting to be good","mean":"The Holy Spirit grows good things like love and kindness in my heart.","age":"all","tags":["shine-kind"]},{"id":"luke-6-31","ref":"Luke 6:31","kjv":"And as ye would that men should do to you, do ye also to them likewise.","say":"I treat others the way I want them to treat me.","theme":"shine-kind","when":"playing with friends","mean":"If I want kindness, I give kindness to others too.","age":"all","tags":["shine-kind","friends-family"]},{"id":"matthew-5-13","ref":"Matthew 5:13","kjv":"Ye are the salt of the earth: but if the salt have lost his savour, wherewith shall it be salted? it is thenceforth good for nothing, but to be cast out, and to be trodden under foot of men.","say":"I am the salt of the earth, and I make things around me better.","theme":"shine-kind","when":"feeling small","mean":"Just as salt makes food better, I can make my world better for others.","age":"7-9","tags":["shine-kind"]},{"id":"matthew-5-14","ref":"Matthew 5:14","kjv":"Ye are the light of the world. A city that is set on an hill cannot be hid.","say":"I am a light in the world, and I can shine for Jesus.","theme":"shine-kind","when":"identity","mean":"Jesus says I am like a light that helps others see His goodness.","age":"all","tags":["shine-kind"]},{"id":"matthew-5-16","ref":"Matthew 5:16","kjv":"Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.","say":"I let my light shine by doing good, so people give praise to God.","theme":"shine-kind","when":"doing good","mean":"When I do kind things, others see God's love and praise Him.","age":"all","tags":["shine-kind"]},{"id":"matthew-5-9","ref":"Matthew 5:9","kjv":"Blessed are the peacemakers: for they shall be called the children of God.","say":"When I make peace, God calls me His child.","theme":"shine-kind","when":"when friends are fighting","mean":"When I help make peace, I show that I belong to God's family.","age":"7-9","tags":["shine-kind","friends-family"]},{"id":"micah-6-8","ref":"Micah 6:8","kjv":"He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?","say":"I do what is right, I love to be kind, and I walk close to God.","theme":"shine-kind","when":"choosing to do right","mean":"God loves it when I am fair, kind, and stay close to Him.","age":"all","tags":["shine-kind"]},{"id":"philippians-2-15","ref":"Philippians 2:15","kjv":"That ye may be blameless and harmless, the sons of God, without rebuke, in the midst of a crooked and perverse nation, among whom ye shine as lights in the world;","say":"I am God's child, and I shine like a little light in the world.","theme":"shine-kind","when":"identity","mean":"As a child of God I shine brightly wherever I go.","age":"4-6","tags":["shine-kind"]},{"id":"proverbs-11-25","ref":"Proverbs 11:25","kjv":"The liberal soul shall be made fat: and he that watereth shall be watered also himself.","say":"I love to give and help others, and God takes loving care of me too.","theme":"shine-kind","when":"sharing","mean":"A generous heart is blessed; as I refresh others, God refreshes me.","age":"7-9","tags":["shine-kind"]},{"id":"proverbs-25-11","ref":"Proverbs 25:11","kjv":"A word fitly spoken is like apples of gold in pictures of silver.","say":"I say the right word at the right time, and it is beautiful like gold.","theme":"shine-kind","when":"saying something kind","mean":"A good word spoken at just the right moment is as lovely as gold.","age":"all","tags":["shine-kind"]},{"id":"proverbs-3-27","ref":"Proverbs 3:27","kjv":"Withhold not good from them to whom it is due, when it is in the power of thine hand to do it.","say":"When I can help someone, I help right away.","theme":"shine-kind","when":"someone needs help","mean":"If I am able to do good for someone, I do it.","age":"4-6","tags":["shine-kind"]},{"id":"proverbs-4-18","ref":"Proverbs 4:18","kjv":"But the path of the just is as the shining light, that shineth more and more unto the perfect day.","say":"As I follow God, my path grows brighter and brighter.","theme":"shine-kind","when":"each new day","mean":"The more I follow God, the brighter and happier my way becomes.","age":"7-9","tags":["shine-kind"]},{"id":"romans-12-10","ref":"Romans 12:10","kjv":"Be kindly affectioned one to another with brotherly love; in honour preferring one another;","say":"I am kind to others, and I gladly let my friends go first.","theme":"shine-kind","when":"being generous","mean":"I love others and happily honour them by letting them be first.","age":"all","tags":["shine-kind","friends-family"]},{"id":"titus-3-2","ref":"Titus 3:2","kjv":"To speak evil of no man, to be no brawlers, but gentle, shewing all meekness unto all men.","say":"I say no mean words about anyone. I am gentle with everyone.","theme":"shine-kind","when":"talking about others","mean":"I don't say mean things about people, and I stay gentle with all.","age":"7-9","tags":["shine-kind"]},{"id":"zechariah-7-9","ref":"Zechariah 7:9","kjv":"Thus speaketh the LORD of hosts, saying, Execute true judgment, and shew mercy and compassions every man to his brother:","say":"I show mercy and kindness to everyone around me.","theme":"shine-kind","when":"including others","mean":"God wants me to be kind and caring to other people.","age":"all","tags":["shine-kind"]},{"id":"1-corinthians-15-57","ref":"1 Corinthians 15:57","kjv":"But thanks be to God, which giveth us the victory through our Lord Jesus Christ.","say":"Thank You, God! You give me the victory through Jesus.","theme":"thankful-praise","when":"thankful","mean":"God is the One who gives me the win, so I say thank You to Him.","age":"all","tags":["thankful-praise"]},{"id":"1-thessalonians-5-18","ref":"1 Thessalonians 5:18","kjv":"In every thing give thanks: for this is the will of God in Christ Jesus concerning you.","say":"In everything, I give thanks — because this is what God wants for me.","theme":"thankful-praise","when":"everyday","mean":"God wants me to say thank You in every kind of day.","age":"all","tags":["thankful-praise"]},{"id":"2-corinthians-9-15","ref":"2 Corinthians 9:15","kjv":"Thanks be unto God for his unspeakable gift.","say":"Thank You, God, for Your very best gift — Jesus!","theme":"thankful-praise","when":"thankful for Jesus","mean":"Jesus is God's most wonderful gift, and I thank Him for it.","age":"4-6","tags":["thankful-praise"]},{"id":"daniel-2-23","ref":"Daniel 2:23","kjv":"I thank thee, and praise thee, O thou God of my fathers, who hast given me wisdom and might, and hast made known unto me now what we desired of thee: for thou hast now made known unto us the king’s matter.","say":"I thank God and praise Him, because He gives me wisdom and makes me strong!","theme":"thankful-praise","when":"a hard test","mean":"God helps me understand things, so I thank Him when I learn.","age":"7-9","tags":["thankful-praise"]},{"id":"ephesians-5-20","ref":"Ephesians 5:20","kjv":"Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ;","say":"I give thanks to God always, for all things, in Jesus' name!","theme":"thankful-praise","when":"thankfulness","mean":"I can thank God for everything, at any time.","age":"7-9","tags":["thankful-praise"]},{"id":"exodus-15-2","ref":"Exodus 15:2","kjv":"The LORD is my strength and song, and he is become my salvation: he is my God, and I will prepare him an habitation; my father’s God, and I will exalt him.","say":"The Lord is my strength and my song, and I will praise Him.","theme":"thankful-praise","when":"thankful","mean":"God makes me strong, so I sing and thank Him with a happy heart.","age":"all","tags":["thankful-praise"]},{"id":"hebrews-13-15","ref":"Hebrews 13:15","kjv":"By him therefore let us offer the sacrifice of praise to God continually, that is, the fruit of our lips giving thanks to his name.","say":"I use my lips to praise God and to thank His name!","theme":"thankful-praise","when":"using my words","mean":"My words can be a happy gift of praise and thanks to God.","age":"7-9","tags":["thankful-praise"]},{"id":"isaiah-12-5","ref":"Isaiah 12:5","kjv":"Sing unto the LORD; for he hath done excellent things: this is known in all the earth.","say":"I sing to God, because He has done excellent, wonderful things!","theme":"thankful-praise","when":"praise","mean":"God does great things, so I sing happy songs to Him.","age":"all","tags":["thankful-praise"]},{"id":"jonah-2-9","ref":"Jonah 2:9","kjv":"But I will sacrifice unto thee with the voice of thanksgiving; I will pay that that I have vowed. Salvation is of the LORD.","say":"I say thank You to God with my happy voice!","theme":"thankful-praise","when":"after trouble","mean":"Even after a scary time, I thank God with a glad voice.","age":"4-6","tags":["thankful-praise"]},{"id":"psalm-100-1","ref":"Psalms 100:1","kjv":"Make a joyful noise unto the LORD, all ye lands.","say":"I will make a joyful noise to the Lord!","theme":"thankful-praise","when":"praise and singing","mean":"I can be loud and happy as I praise God.","age":"4-6","tags":["thankful-praise"]},{"id":"psalms-100-4","ref":"Psalms 100:4","kjv":"Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name.","say":"I come to God with a thank You, and I bless His name.","theme":"thankful-praise","when":"prayer time","mean":"When I come to God, I bring a thankful heart and happy praise.","age":"all","tags":["thankful-praise"]},{"id":"psalms-107-1","ref":"Psalms 107:1","kjv":"O give thanks unto the LORD, for he is good: for his mercy endureth for ever.","say":"I say thank You to God, because He is so good.","theme":"thankful-praise","when":"thankfulness","mean":"God is good all the time, so I can always thank Him.","age":"4-6","tags":["thankful-praise"]},{"id":"psalms-150-6","ref":"Psalms 150:6","kjv":"Let every thing that hath breath praise the LORD. Praise ye the LORD.","say":"I have breath, so I use it to praise God!","theme":"thankful-praise","when":"praise","mean":"Everyone who can breathe can praise God, and that means me too.","age":"all","tags":["thankful-praise"]},{"id":"psalms-34-1","ref":"Psalms 34:1","kjv":"I will bless the LORD at all times: his praise shall continually be in my mouth.","say":"I bless God all the time, and His praise is always on my lips!","theme":"thankful-praise","when":"all day","mean":"I can thank and praise God every moment, not just sometimes.","age":"7-9","tags":["thankful-praise"]},{"id":"psalms-59-16","ref":"Psalms 59:16","kjv":"But I will sing of thy power; yea, I will sing aloud of thy mercy in the morning: for thou hast been my defence and refuge in the day of my trouble.","say":"In the morning I sing out loud about God's power and His love!","theme":"thankful-praise","when":"morning","mean":"When I wake up, I can sing because God keeps me safe.","age":"4-6","tags":["thankful-praise"]},{"id":"psalms-9-1","ref":"Psalms 9:1","kjv":"I will praise thee, O LORD, with my whole heart; I will shew forth all thy marvellous works.","say":"I praise God with my whole heart, and I tell about the wonderful things He does!","theme":"thankful-praise","when":"telling others","mean":"I love God with all my heart and talk about His amazing works.","age":"7-9","tags":["thankful-praise"]},{"id":"1-john-4-4","ref":"1 John 4:4","kjv":"Ye are of God, little children, and have overcome them: because greater is he that is in you, than he that is in the world.","say":"God who lives in me is bigger than anything in the whole world.","theme":"victory-overcomer","when":"afraid","mean":"God's Spirit inside me is greater than anything that tries to scare me.","age":"all","tags":["victory-overcomer"]},{"id":"1-john-5-4","ref":"1 John 5:4","kjv":"For whatsoever is born of God overcometh the world: and this is the victory that overcometh the world, even our faith.","say":"I belong to God, and my faith in Him helps me win over hard things.","theme":"victory-overcomer","when":"victory","mean":"Because I belong to God and trust Him, my faith helps me overcome.","age":"7-9","tags":["victory-overcomer"]},{"id":"1-samuel-17-47","ref":"1 Samuel 17:47","kjv":"And all this assembly shall know that the LORD saveth not with sword and spear: for the battle is the LORD’s, and he will give you into our hands.","say":"The battle belongs to God, and He fights for me.","theme":"victory-overcomer","when":"facing something big","mean":"Just like with David and Goliath, God fights my big battles for me.","age":"all","tags":["victory-overcomer"]},{"id":"2-corinthians-12-9","ref":"2 Corinthians 12:9","kjv":"And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me.","say":"When I feel weak and small, God's strength is made perfect in me.","theme":"victory-overcomer","when":"feeling small","mean":"Even when I'm not strong, God's grace is enough and His power helps me.","age":"7-9","tags":["victory-overcomer"]},{"id":"2-corinthians-2-14","ref":"2 Corinthians 2:14","kjv":"Now thanks be unto God, which always causeth us to triumph in Christ, and maketh manifest the savour of his knowledge by us in every place.","say":"God always leads me to win, because I belong to Jesus.","theme":"victory-overcomer","when":"triumph","mean":"God always leads me to victory because I belong to Jesus.","age":"all","tags":["victory-overcomer"]},{"id":"ephesians-6-10","ref":"Ephesians 6:10","kjv":"Finally, my brethren, be strong in the Lord, and in the power of his might.","say":"I am strong in the Lord and in His mighty power.","theme":"victory-overcomer","when":"facing something hard","mean":"I don't have to be strong all by myself—God's big strength is in me.","age":"7-9","tags":["victory-overcomer"]},{"id":"habakkuk-3-19","ref":"Habakkuk 3:19","kjv":"The LORD God is my strength, and he will make my feet like hinds’ feet, and he will make me to walk upon mine high places. To the chief singer on my stringed instruments.","say":"The Lord God is my strength, and He helps me climb like a deer.","theme":"victory-overcomer","when":"a hard climb","mean":"God steadies my feet and helps me go up the hard, high places.","age":"7-9","tags":["victory-overcomer"]},{"id":"isaiah-40-29","ref":"Isaiah 40:29","kjv":"He giveth power to the faint; and to them that have no might he increaseth strength.","say":"When I am tired and have no strength, God gives me more.","theme":"victory-overcomer","when":"worn out","mean":"When I feel like I can't go on, God gives power to the tired.","age":"7-9","tags":["victory-overcomer"]},{"id":"isaiah-40-31","ref":"Isaiah 40:31","kjv":"But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.","say":"When I wait on God, He gives me fresh strength, so I do not get too tired.","theme":"victory-overcomer","when":"tired","mean":"When I feel worn out, God renews my strength so I run and do not grow weary.","age":"7-9","tags":["victory-overcomer"]},{"id":"john-16-33","ref":"John 16:33","kjv":"These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.","say":"In Jesus I have peace, and I can be happy because He has already won.","theme":"victory-overcomer","when":"a hard day","mean":"Jesus already beat every hard thing, so I can cheer up even on tough days.","age":"all","tags":["victory-overcomer"]},{"id":"luke-10-19","ref":"Luke 10:19","kjv":"Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy: and nothing shall by any means hurt you.","say":"Jesus gives me power over the enemy, so I do not have to be afraid.","theme":"victory-overcomer","when":"scared of the enemy","mean":"Jesus gives me His power over the enemy, so I do not have to be afraid.","age":"7-9","tags":["victory-overcomer"]},{"id":"micah-7-8","ref":"Micah 7:8","kjv":"Rejoice not against me, O mine enemy: when I fall, I shall arise; when I sit in darkness, the LORD shall be a light unto me.","say":"When I fall, I get back up again, because the Lord is my light.","theme":"victory-overcomer","when":"made a mistake","mean":"Even when I mess up or fall, God helps me rise again and lights my way.","age":"all","tags":["victory-overcomer"]},{"id":"philippians-4-13","ref":"Philippians 4:13","kjv":"I can do all things through Christ which strengtheneth me.","say":"I can do all things through Christ, who makes me strong.","theme":"victory-overcomer","when":"a hard test","mean":"Jesus gives me strength to do hard things, even when they feel too big.","age":"all","tags":["victory-overcomer","wise-learner"]},{"id":"psalm-73-26","ref":"Psalms 73:26","kjv":"My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever.","say":"Even when I feel weak, God is the strength of my heart forever.","theme":"victory-overcomer","when":"feeling weak","mean":"My body gets tired, but God keeps my heart strong and never lets go.","age":"7-9","tags":["victory-overcomer"]},{"id":"romans-16-20","ref":"Romans 16:20","kjv":"And the God of peace shall bruise Satan under your feet shortly. The grace of our Lord Jesus Christ be with you. Amen.","say":"The God of peace gives me peace and puts the enemy under my feet.","theme":"victory-overcomer","when":"treading on the enemy","mean":"God, who gives peace, wins the victory over the enemy for me.","age":"7-9","tags":["victory-overcomer"]},{"id":"romans-5-17","ref":"Romans 5:17","kjv":"For if by one man’s offence death reigned by one; much more they which receive abundance of grace and of the gift of righteousness shall reign in life by one, Jesus Christ.)","say":"Because of Jesus, I reign in life as one of God's children.","theme":"victory-overcomer","when":"identity","mean":"Jesus gives me so much grace that I can live above my problems, not under them.","age":"7-9","tags":["victory-overcomer"]},{"id":"romans-8-37","ref":"Romans 8:37","kjv":"Nay, in all these things we are more than conquerors through him that loved us.","say":"I am more than a conqueror, because Jesus loves me.","theme":"victory-overcomer","when":"facing something hard","mean":"Because Jesus loves me, I can come through anything that happens to me.","age":"all","tags":["victory-overcomer"]},{"id":"zechariah-4-6","ref":"Zechariah 4:6","kjv":"Then he answered and spake unto me, saying, This is the word of the LORD unto Zerubbabel, saying, Not by might, nor by power, but by my spirit, saith the LORD of hosts.","say":"Not by my own strength, but by God's Spirit, I can do what He asks.","theme":"victory-overcomer","when":"feeling too small","mean":"Big things happen by God's Spirit helping me, not by how strong I am.","age":"7-9","tags":["victory-overcomer"]},{"id":"1-corinthians-3-16","ref":"1 Corinthians 3:16","kjv":"Know ye not that ye are the temple of God, and that the Spirit of God dwelleth in you?","say":"I am God's temple, and His Spirit lives in me.","theme":"who-i-am","when":"identity","mean":"Your life is a special home where God's Spirit lives.","age":"7-9","tags":["who-i-am"]},{"id":"1-corinthians-6-11","ref":"1 Corinthians 6:11","kjv":"And such were some of you: but ye are washed, but ye are sanctified, but ye are justified in the name of the Lord Jesus, and by the Spirit of our God.","say":"I am washed, I am clean, and I am made right, in Jesus' name.","theme":"who-i-am","when":"feeling dirty inside","mean":"In Jesus you are washed clean and made right with God.","age":"7-9","tags":["who-i-am"]},{"id":"1-corinthians-6-19","ref":"1 Corinthians 6:19","kjv":"What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own?","say":"My body is a special home for God's Holy Spirit.","theme":"who-i-am","when":"taking care of myself","mean":"God's Spirit lives in your body, so your body is special to God.","age":"7-9","tags":["who-i-am"]},{"id":"1-john-4-13","ref":"1 John 4:13","kjv":"Hereby know we that we dwell in him, and he in us, because he hath given us of his Spirit.","say":"I live in God and He lives in me, because He gave me His Spirit.","theme":"who-i-am","when":"feeling unsure","mean":"God gave me His Spirit to show for sure that I belong to Him.","age":"7-9","tags":["who-i-am"]},{"id":"1-peter-2-9","ref":"1 Peter 2:9","kjv":"But ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people; that ye should shew forth the praises of him who hath called you out of darkness into his marvellous light:","say":"I am chosen by God, part of His royal family, and I shine His light.","theme":"who-i-am","when":"feeling ordinary","mean":"God picked me to belong to Him, like royalty, and I show His light to others.","age":"7-9","tags":["who-i-am"]},{"id":"2-corinthians-5-17","ref":"2 Corinthians 5:17","kjv":"Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new.","say":"I am a new creature in Jesus! My old things are gone and everything is brand new.","theme":"who-i-am","when":"identity","mean":"When you belong to Jesus, God makes you brand new inside and your old self is gone.","age":"all","tags":["who-i-am"]},{"id":"2-corinthians-5-21","ref":"2 Corinthians 5:21","kjv":"For he hath made him to be sin for us, who knew no sin; that we might be made the righteousness of God in him.","say":"In Jesus, I am made right with God!","theme":"who-i-am","when":"not good enough","mean":"Because of Jesus, God sees you as good and right with Him.","age":"7-9","tags":["who-i-am"]},{"id":"2-corinthians-6-16","ref":"2 Corinthians 6:16","kjv":"And what agreement hath the temple of God with idols? for ye are the temple of the living God; as God hath said, I will dwell in them, and walk in them; and I will be their God, and they shall be my people.","say":"I am a temple of the living God, and He lives and walks in me.","theme":"who-i-am","when":"identity","mean":"God Himself promised to live and walk in His people, and I am one of them.","age":"7-9","tags":["who-i-am"]},{"id":"2-corinthians-6-18","ref":"2 Corinthians 6:18","kjv":"And will be a Father unto you, and ye shall be my sons and daughters, saith the Lord Almighty.","say":"God is my Father, and I am His own child.","theme":"who-i-am","when":"missing a parent","mean":"God promises to be my Father and to call me His own son or daughter.","age":"all","tags":["who-i-am"]},{"id":"2-timothy-1-14","ref":"2 Timothy 1:14","kjv":"That good thing which was committed unto thee keep by the Holy Ghost which dwelleth in us.","say":"The Holy Spirit lives in me and helps me hold on to what is good.","theme":"who-i-am","when":"wanting to hold on to good","mean":"The Holy Spirit who lives in me helps me keep the good things God gives.","age":"7-9","tags":["who-i-am"]},{"id":"colossians-1-14","ref":"Colossians 1:14","kjv":"In whom we have redemption through his blood, even the forgiveness of sins:","say":"Jesus paid for me with His own blood, so all my sins are forgiven!","theme":"who-i-am","when":"forgiven","mean":"Jesus gave His life to buy you back, so every wrong thing you did is forgiven.","age":"7-9","tags":["who-i-am"]},{"id":"colossians-3-10","ref":"Colossians 3:10","kjv":"And have put on the new man, which is renewed in knowledge after the image of him that created him:","say":"I have put on the new me, and God makes me more like Him every day.","theme":"who-i-am","when":"growing","mean":"God is helping you become a new person who looks more like Him each day.","age":"7-9","tags":["who-i-am"]},{"id":"deuteronomy-14-1","ref":"Deuteronomy 14:1","kjv":"Ye are the children of the LORD your God: ye shall not cut yourselves, nor make any baldness between your eyes for the dead.","say":"I am a child of the Lord my God.","theme":"who-i-am","when":"wondering who I am","mean":"God calls His people His own children, and I am one of them.","age":"4-6","tags":["who-i-am"]},{"id":"deuteronomy-7-6","ref":"Deuteronomy 7:6","kjv":"For thou art an holy people unto the LORD thy God: the LORD thy God hath chosen thee to be a special people unto himself, above all people that are upon the face of the earth.","say":"I belong to God, and He chose me to be His very own special child.","theme":"who-i-am","when":"feeling ordinary","mean":"God picked me to belong to Him and to be set apart as His own.","age":"all","tags":["who-i-am"]},{"id":"ephesians-1-13","ref":"Ephesians 1:13","kjv":"In whom ye also trusted, after that ye heard the word of truth, the gospel of your salvation: in whom also after that ye believed, ye were sealed with that holy Spirit of promise,","say":"God put His Holy Spirit on me like a stamp that says I belong to Him.","theme":"who-i-am","when":"being left out","mean":"When I believed, God sealed me with the Holy Spirit as a mark that I am truly His.","age":"7-9","tags":["who-i-am"]},{"id":"ephesians-1-4","ref":"Ephesians 1:4","kjv":"According as he hath chosen us in him before the foundation of the world, that we should be holy and without blame before him in love:","say":"God chose me in Jesus before the world even began.","theme":"who-i-am","when":"belonging","mean":"Before God made the world, He already wanted me to be His.","age":"7-9","tags":["who-i-am"]},{"id":"ephesians-1-5","ref":"Ephesians 1:5","kjv":"Having predestinated us unto the adoption of children by Jesus Christ to himself, according to the good pleasure of his will,","say":"God chose to make me part of His family.","theme":"who-i-am","when":"feeling left out","mean":"God wanted me, so He planned to adopt me as His own child through Jesus.","age":"all","tags":["who-i-am"]},{"id":"ephesians-2-10","ref":"Ephesians 2:10","kjv":"For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them.","say":"I am God's handiwork, made in Christ to do good things.","theme":"who-i-am","when":"feeling useless","mean":"I am something God carefully made, and He has good things for me to do.","age":"7-9","tags":["who-i-am"]},{"id":"ephesians-2-19","ref":"Ephesians 2:19","kjv":"Now therefore ye are no more strangers and foreigners, but fellowcitizens with the saints, and of the household of God;","say":"I am not a stranger - I belong in God's family.","theme":"who-i-am","when":"being left out","mean":"I am not an outsider; I belong in God's house as part of His household.","age":"all","tags":["who-i-am"]},{"id":"ephesians-2-8","ref":"Ephesians 2:8","kjv":"For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:","say":"I am saved because of God's love — it is His free gift to me!","theme":"who-i-am","when":"grace","mean":"Being saved is a present from God — you can't buy it or earn it; He gives it freely.","age":"all","tags":["who-i-am"]},{"id":"ephesians-3-17","ref":"Ephesians 3:17","kjv":"That Christ may dwell in your hearts by faith; that ye, being rooted and grounded in love,","say":"Jesus lives in my heart because I trust Him.","theme":"who-i-am","when":"identity","mean":"When I trust Jesus, He makes His home right inside my heart.","age":"4-6","tags":["who-i-am"]},{"id":"ezekiel-36-26","ref":"Ezekiel 36:26","kjv":"A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh.","say":"God gives me a brand new heart and a brand new spirit!","theme":"who-i-am","when":"wanting to change","mean":"God takes away your hard, cold heart and gives you a soft, new, loving heart.","age":"all","tags":["who-i-am"]},{"id":"galatians-3-26","ref":"Galatians 3:26","kjv":"For ye are all the children of God by faith in Christ Jesus.","say":"When I trust Jesus, I am a child of God.","theme":"who-i-am","when":"identity","mean":"Faith in Jesus makes me part of God's family.","age":"all","tags":["who-i-am"]},{"id":"galatians-4-7","ref":"Galatians 4:7","kjv":"Wherefore thou art no more a servant, but a son; and if a son, then an heir of God through Christ.","say":"I am not just a servant - I am God's own child and heir.","theme":"who-i-am","when":"feeling small","mean":"God does not treat me like a stranger or a servant; He treats me as His own child through Christ.","age":"7-9","tags":["who-i-am"]},{"id":"genesis-1-27","ref":"Genesis 1:27","kjv":"So God created man in his own image, in the image of God created he him; male and female created he them.","say":"God made me in His own image.","theme":"who-i-am","when":"identity","mean":"God made me to be like Him in love and goodness.","age":"all","tags":["who-i-am"]},{"id":"isaiah-1-18","ref":"Isaiah 1:18","kjv":"Come now, and let us reason together, saith the LORD: though your sins be as scarlet, they shall be as white as snow; though they be red like crimson, they shall be as wool.","say":"Jesus washes my sins away and makes me white as snow.","theme":"who-i-am","when":"after doing wrong","mean":"Even if you did something very wrong, Jesus can make your heart clean and white like fresh snow.","age":"all","tags":["who-i-am"]},{"id":"isaiah-41-9","ref":"Isaiah 41:9","kjv":"Thou whom I have taken from the ends of the earth, and called thee from the chief men thereof, and said unto thee, Thou art my servant; I have chosen thee, and not cast thee away.","say":"God chose me and will never throw me away.","theme":"who-i-am","when":"feeling rejected","mean":"God chose you on purpose and promises He will never throw you away.","age":"all","tags":["who-i-am"]},{"id":"isaiah-43-1","ref":"Isaiah 43:1","kjv":"But now thus saith the LORD that created thee, O Jacob, and he that formed thee, O Israel, Fear not: for I have redeemed thee, I have called thee by thy name; thou art mine.","say":"I will not be afraid, because God calls me by my name and says I am His.","theme":"who-i-am","when":"feeling afraid","mean":"God made me, knows my name, and says I belong to Him, so I do not need to be scared.","age":"4-6","tags":["who-i-am"]},{"id":"isaiah-43-25","ref":"Isaiah 43:25","kjv":"I, even I, am he that blotteth out thy transgressions for mine own sake, and will not remember thy sins.","say":"God wipes my sins away and remembers them no more!","theme":"who-i-am","when":"guilt that lingers","mean":"God erases the wrong things you did and chooses not to remember them.","age":"7-9","tags":["who-i-am"]},{"id":"isaiah-62-3","ref":"Isaiah 62:3","kjv":"Thou shalt also be a crown of glory in the hand of the LORD, and a royal diadem in the hand of thy God.","say":"I am precious to God, like a beautiful crown held in His own hand.","theme":"who-i-am","when":"feeling small","mean":"To God I am as beautiful and treasured as a king's crown.","age":"all","tags":["who-i-am"]},{"id":"isaiah-64-8","ref":"Isaiah 64:8","kjv":"But now, O LORD, thou art our father; we are the clay, and thou our potter; and we all are the work of thy hand.","say":"I am the work of God's hands, like clay shaped by the potter.","theme":"who-i-am","when":"feeling like a mess-up","mean":"God is shaping me like a potter shapes clay, and I am His good work.","age":"7-9","tags":["who-i-am"]},{"id":"jeremiah-1-5","ref":"Jeremiah 1:5","kjv":"Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations.","say":"Before I was born, God already knew me, and I belong to Him.","theme":"who-i-am","when":"feeling unseen","mean":"God knew me and loved me before I was born, so I always belonged to Him.","age":"7-9","tags":["who-i-am"]},{"id":"job-33-4","ref":"Job 33:4","kjv":"The Spirit of God hath made me, and the breath of the Almighty hath given me life.","say":"God made me and gave me my very breath.","theme":"who-i-am","when":"feeling sad","mean":"My life is a gift from God, who made me and gives me breath.","age":"all","tags":["who-i-am"]},{"id":"john-1-12","ref":"John 1:12","kjv":"But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name:","say":"I believe in Jesus, so I am a child of God!","theme":"who-i-am","when":"identity","mean":"When I receive Jesus and believe in His name, God gives me the right to be His very own child.","age":"all","tags":["who-i-am"]},{"id":"john-15-16","ref":"John 15:16","kjv":"Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you.","say":"Jesus chose me on purpose — I am never left out!","theme":"who-i-am","when":"being left out","mean":"Jesus chose me first; I never had to earn my place.","age":"all","tags":["who-i-am"]},{"id":"john-15-4","ref":"John 15:4","kjv":"Abide in me, and I in you. As the branch cannot bear fruit of itself, except it abide in the vine; no more can ye, except ye abide in me.","say":"I stay close to Jesus, and Jesus stays in me.","theme":"who-i-am","when":"feeling far from God","mean":"When I stay close to Jesus, He stays in me and helps me grow.","age":"4-6","tags":["who-i-am"]},{"id":"luke-12-7","ref":"Luke 12:7","kjv":"But even the very hairs of your head are all numbered. Fear not therefore: ye are of more value than many sparrows.","say":"God knows me so well He has counted every hair on my head.","theme":"who-i-am","when":"afraid","mean":"God knows every little thing about me, and I am precious to Him.","age":"4-6","tags":["who-i-am"]},{"id":"matthew-10-31","ref":"Matthew 10:31","kjv":"Fear ye not therefore, ye are of more value than many sparrows.","say":"I don't need to be afraid, because I am precious to God — worth more than many sparrows!","theme":"who-i-am","when":"afraid","mean":"God values me so highly that I never need to be afraid.","age":"4-6","tags":["who-i-am"]},{"id":"micah-7-19","ref":"Micah 7:19","kjv":"He will turn again, he will have compassion upon us; he will subdue our iniquities; and thou wilt cast all their sins into the depths of the sea.","say":"God throws all my sins into the deep, deep sea!","theme":"who-i-am","when":"forgiven","mean":"God throws your sins into the deepest sea where they are gone for good.","age":"4-6","tags":["who-i-am"]},{"id":"philippians-3-20","ref":"Philippians 3:20","kjv":"For our conversation is in heaven; from whence also we look for the Saviour, the Lord Jesus Christ:","say":"My true home is in heaven, where Jesus my Saviour is.","theme":"who-i-am","when":"feeling like I don't fit in","mean":"Heaven is my true home, because I belong to Jesus my Saviour.","age":"7-9","tags":["who-i-am"]},{"id":"psalm-139-14","ref":"Psalms 139:14","kjv":"I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well.","say":"I am fearfully and wonderfully made, just the way God planned.","theme":"who-i-am","when":"feeling not good enough","mean":"God carefully made me wonderful on purpose, so I can thank Him for how He made me.","age":"all","tags":["who-i-am"]},{"id":"psalms-100-3","ref":"Psalms 100:3","kjv":"Know ye that the LORD he is God: it is he that hath made us, and not we ourselves; we are his people, and the sheep of his pasture.","say":"God made me, and I belong to Him like a sheep He loves and keeps.","theme":"who-i-am","when":"bedtime","mean":"God made me and cares for me like a good shepherd cares for his sheep.","age":"4-6","tags":["who-i-am"]},{"id":"psalms-103-12","ref":"Psalms 103:12","kjv":"As far as the east is from the west, so far hath he removed our transgressions from us.","say":"God took my sins far, far away — as far as the east is from the west!","theme":"who-i-am","when":"forgiven","mean":"God takes the wrong things you did and moves them so far away they can never come back.","age":"4-6","tags":["who-i-am"]},{"id":"psalms-119-73","ref":"Psalms 119:73","kjv":"Thy hands have made me and fashioned me: give me understanding, that I may learn thy commandments.","say":"God's own hands made me and shaped me.","theme":"who-i-am","when":"a hard test","mean":"God made me with His hands and He helps me understand.","age":"7-9","tags":["who-i-am"]},{"id":"psalms-139-13","ref":"Psalms 139:13","kjv":"For thou hast possessed my reins: thou hast covered me in my mother’s womb.","say":"God made me and watched over me before I was born.","theme":"who-i-am","when":"bedtime","mean":"God took care of me even before I was born.","age":"4-6","tags":["who-i-am"]},{"id":"psalms-4-3","ref":"Psalms 4:3","kjv":"But know that the LORD hath set apart him that is godly for himself: the LORD will hear when I call unto him.","say":"God set me apart for Himself, and He hears me when I call.","theme":"who-i-am","when":"feeling different","mean":"God set you apart to belong to Him, and He listens every single time you pray.","age":"7-9","tags":["who-i-am"]},{"id":"psalms-51-7","ref":"Psalms 51:7","kjv":"Purge me with hyssop, and I shall be clean: wash me, and I shall be whiter than snow.","say":"When God washes me, I am clean — whiter than snow!","theme":"who-i-am","when":"feeling dirty inside","mean":"You can ask God to wash you, and He makes you cleaner than the whitest snow.","age":"7-9","tags":["who-i-am"]},{"id":"psalms-8-5","ref":"Psalms 8:5","kjv":"For thou hast made him a little lower than the angels, and hast crowned him with glory and honour.","say":"God made me special and crowned me with glory and honour.","theme":"who-i-am","when":"feeling small","mean":"God gave me real dignity and honour; I am not small in His eyes.","age":"7-9","tags":["who-i-am"]},{"id":"revelation-21-7","ref":"Revelation 21:7","kjv":"He that overcometh shall inherit all things; and I will be his God, and he shall be my son.","say":"I am God's child, and He will be my God forever.","theme":"who-i-am","when":"bedtime","mean":"God promises that I am His child and He will be my God forever.","age":"7-9","tags":["who-i-am"]},{"id":"romans-8-1","ref":"Romans 8:1","kjv":"There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit.","say":"In Jesus, there is no condemnation for me — I am not in trouble with God!","theme":"who-i-am","when":"shame","mean":"When you belong to Jesus, God is not angry with you — you are not in trouble.","age":"7-9","tags":["who-i-am"]},{"id":"romans-8-11","ref":"Romans 8:11","kjv":"But if the Spirit of him that raised up Jesus from the dead dwell in you, he that raised up Christ from the dead shall also quicken your mortal bodies by his Spirit that dwelleth in you.","say":"The same Spirit who raised Jesus from the dead lives in me.","theme":"who-i-am","when":"feeling weak","mean":"God's mighty Spirit, the One who raised Jesus, lives inside me.","age":"7-9","tags":["who-i-am"]},{"id":"romans-8-16","ref":"Romans 8:16","kjv":"The Spirit itself beareth witness with our spirit, that we are the children of God:","say":"God's Spirit tells my heart that I am His child.","theme":"who-i-am","when":"needing assurance","mean":"God's own Spirit helps me know deep inside that I truly belong to Him.","age":"7-9","tags":["who-i-am"]},{"id":"romans-8-17","ref":"Romans 8:17","kjv":"And if children, then heirs; heirs of God, and joint-heirs with Christ; if so be that we suffer with him, that we may be also glorified together.","say":"I am God's child, and His promises are mine together with Jesus.","theme":"who-i-am","when":"identity","mean":"Because I am God's child, I share in His good promises, just as Jesus does.","age":"7-9","tags":["who-i-am"]},{"id":"romans-8-9","ref":"Romans 8:9","kjv":"But ye are not in the flesh, but in the Spirit, if so be that the Spirit of God dwell in you. Now if any man have not the Spirit of Christ, he is none of his.","say":"I belong to God, because His Spirit lives in me.","theme":"who-i-am","when":"identity","mean":"The Spirit of God lives in me, so I am truly His.","age":"7-9","tags":["who-i-am"]},{"id":"titus-2-14","ref":"Titus 2:14","kjv":"Who gave himself for us, that he might redeem us from all iniquity, and purify unto himself a peculiar people, zealous of good works.","say":"Jesus gave Himself to make me His very own.","theme":"who-i-am","when":"feeling like an outsider","mean":"Jesus gave His whole self for you so you could belong to Him as His very own.","age":"7-9","tags":["who-i-am"]},{"id":"titus-3-5","ref":"Titus 3:5","kjv":"Not by works of righteousness which we have done, but according to his mercy he saved us, by the washing of regeneration, and renewing of the Holy Ghost;","say":"God saved me and made me new because of His mercy, not because I earned it!","theme":"who-i-am","when":"identity","mean":"God made you new because He is loving and merciful, not because you were perfect.","age":"7-9","tags":["who-i-am"]},{"id":"2-timothy-3-15","ref":"2 Timothy 3:15","kjv":"And that from a child thou hast known the holy scriptures, which are able to make thee wise unto salvation through faith which is in Christ Jesus.","say":"Even now, while I am a child, God's Word makes me wise, wise to know and trust Jesus.","theme":"wise-learner","when":"reading the Bible","mean":"I don't have to be grown up to be wise; God's Word makes me wise to know Jesus, even now.","age":"all","tags":["wise-learner"]},{"id":"colossians-2-3","ref":"Colossians 2:3","kjv":"In whom are hid all the treasures of wisdom and knowledge.","say":"In Jesus are hidden all the treasures of wisdom and knowledge.","theme":"wise-learner","when":"wanting to be wise","mean":"Every treasure of wisdom and knowledge is found in Jesus.","age":"7-9","tags":["wise-learner"]},{"id":"daniel-1-17","ref":"Daniel 1:17","kjv":"As for these four children, God gave them knowledge and skill in all learning and wisdom: and Daniel had understanding in all visions and dreams.","say":"God gives me knowledge and skill in all my learning.","theme":"wise-learner","when":"school","mean":"Just as He gave Daniel and his friends skill in their learning, God helps me learn.","age":"all","tags":["wise-learner"]},{"id":"daniel-2-21","ref":"Daniel 2:21","kjv":"And he changeth the times and the seasons: he removeth kings, and setteth up kings: he giveth wisdom unto the wise, and knowledge to them that know understanding:","say":"God gives wisdom and knowledge; He is the One who makes me wise.","theme":"wise-learner","when":"learning","mean":"God is the source of all wisdom and knowledge, so I look to Him.","age":"7-9","tags":["wise-learner"]},{"id":"isaiah-54-13","ref":"Isaiah 54:13","kjv":"And all thy children shall be taught of the LORD; and great shall be the peace of thy children.","say":"I am God's child, and He Himself teaches me; He gives me great peace.","theme":"wise-learner","when":"identity","mean":"I am one of God's children, and He Himself teaches me and gives me peace.","age":"all","tags":["wise-learner"]},{"id":"james-1-5","ref":"James 1:5","kjv":"If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.","say":"When I don't know what to do, I ask God, and He gives me wisdom.","theme":"wise-learner","when":"a hard problem","mean":"When I need to be wise, I can simply ask God and He loves to give it.","age":"all","tags":["wise-learner"]},{"id":"james-3-17","ref":"James 3:17","kjv":"But the wisdom that is from above is first pure, then peaceable, gentle, and easy to be intreated, full of mercy and good fruits, without partiality, and without hypocrisy.","say":"God's wisdom from above makes me pure, gentle, kind, and peaceable.","theme":"wise-learner","when":"being kind","mean":"True wisdom from God makes me gentle and good to the people around me.","age":"7-9","tags":["wise-learner"]},{"id":"jeremiah-33-3","ref":"Jeremiah 33:3","kjv":"Call unto me, and I will answer thee, and shew thee great and mighty things, which thou knowest not.","say":"When I call on God, He answers me and shows me wonderful things.","theme":"wise-learner","when":"curious","mean":"God loves to answer me and show me great things I never knew before.","age":"all","tags":["wise-learner"]},{"id":"proverbs-2-6","ref":"Proverbs 2:6","kjv":"For the LORD giveth wisdom: out of his mouth cometh knowledge and understanding.","say":"God gives me wisdom, and understanding comes from Him.","theme":"wise-learner","when":"learning","mean":"Wisdom and understanding are gifts that come from God Himself.","age":"7-9","tags":["wise-learner"]},{"id":"proverbs-3-5","ref":"Proverbs 3:5","kjv":"Trust in the LORD with all thine heart; and lean not unto thine own understanding.","say":"I trust God with all my heart, even when I don't understand.","theme":"wise-learner","when":"when confused","mean":"When things don't make sense, I lean on God's understanding instead of my own.","age":"all","tags":["wise-learner"]},{"id":"proverbs-9-10","ref":"Proverbs 9:10","kjv":"The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.","say":"Wisdom begins when I love and honor God with all my heart.","theme":"wise-learner","when":"learning to be wise","mean":"The very first step to being wise is loving and honoring God.","age":"7-9","tags":["wise-learner"]},{"id":"psalm-119-105","ref":"Psalms 119:105","kjv":"Thy word is a lamp unto my feet, and a light unto my path.","say":"God's Word is a lamp for my feet and a light for my path; it shows me the way to go.","theme":"wise-learner","when":"bedtime","mean":"The Bible is like a lamp that helps me see the right path, even in the dark.","age":"all","tags":["wise-learner"]},{"id":"psalm-119-130","ref":"Psalms 119:130","kjv":"The entrance of thy words giveth light; it giveth understanding unto the simple.","say":"When God's words come into my heart, they give me light and help me understand.","theme":"wise-learner","when":"understanding","mean":"God's words turn the light on inside me so I can understand.","age":"7-9","tags":["wise-learner"]},{"id":"psalm-25-4","ref":"Psalms 25:4","kjv":"Shew me thy ways, O LORD; teach me thy paths.","say":"Show me Your ways, O Lord, and teach me Your paths; I want to learn from You.","theme":"wise-learner","when":"a prayer to learn","mean":"I can ask God to be my teacher and show me the right way.","age":"4-6","tags":["wise-learner"]},{"id":"psalm-32-8","ref":"Psalms 32:8","kjv":"I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye.","say":"God promises to teach me and guide me in the way I should go.","theme":"wise-learner","when":"needing direction","mean":"God promises to teach me and guide me, step by step.","age":"all","tags":["wise-learner"]},{"id":"psalms-119-34","ref":"Psalms 119:34","kjv":"Give me understanding, and I shall keep thy law; yea, I shall observe it with my whole heart.","say":"God gives me understanding, so I can do what is right.","theme":"wise-learner","when":"wanting to obey","mean":"When God helps me understand His word, I can keep it with my whole heart.","age":"7-9","tags":["wise-learner"]},{"id":"psalms-19-7","ref":"Psalms 19:7","kjv":"The law of the LORD is perfect, converting the soul: the testimony of the LORD is sure, making wise the simple.","say":"God's word makes even a little one like me wise.","theme":"wise-learner","when":"feeling small","mean":"I may be young and small, but God's word can make me wise.","age":"4-6","tags":["wise-learner"]},{"id":"1-john-4-7","ref":"1 John 4:7","kjv":"Beloved, let us love one another: for love is of God; and every one that loveth is born of God, and knoweth God.","say":"Love comes from God, so God's love helps me love others.","theme":"friends-family","when":"loving my family","mean":"Love comes from God, so I can share it at home.","age":"all","tags":["friends-family"]},{"id":"1-peter-4-9","ref":"1 Peter 4:9","kjv":"Use hospitality one to another without grudging.","say":"I welcome others and share with a happy heart, not a grumpy one.","theme":"friends-family","when":"making friends","mean":"I welcome people happily, not grumpily.","age":"4-6","tags":["friends-family"]},{"id":"1-samuel-18-1","ref":"1 Samuel 18:1","kjv":"And it came to pass, when he had made an end of speaking unto Saul, that the soul of Jonathan was knit with the soul of David, and Jonathan loved him as his own soul.","say":"Jonathan loved his friend David with all his heart, and I can love my friends like that.","theme":"friends-family","when":"my best friend","mean":"Jonathan and David were true best friends.","age":"7-9","tags":["friends-family"]},{"id":"acts-16-31","ref":"Acts 16:31","kjv":"And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house.","say":"I believe in Jesus, and I pray that my whole family will love Him too.","theme":"friends-family","when":"family that loves God together","mean":"Jesus can save me and my whole family.","age":"7-9","tags":["friends-family"]},{"id":"colossians-3-13","ref":"Colossians 3:13","kjv":"Forbearing one another, and forgiving one another, if any man have a quarrel against any: even as Christ forgave you, so also do ye.","say":"When someone upsets me, I forgive them, just like Jesus forgives me.","theme":"friends-family","when":"my brother or sister","mean":"I forgive others the same way Jesus forgives me.","age":"7-9","tags":["friends-family"]},{"id":"colossians-3-20","ref":"Colossians 3:20","kjv":"Children, obey your parents in all things: for this is well pleasing unto the Lord.","say":"I obey my mum and dad in everything, and this makes the Lord happy.","theme":"friends-family","when":"obeying mum and dad","mean":"Obeying my parents makes God smile.","age":"4-6","tags":["friends-family"]},{"id":"deuteronomy-5-16","ref":"Deuteronomy 5:16","kjv":"Honour thy father and thy mother, as the LORD thy God hath commanded thee; that thy days may be prolonged, and that it may go well with thee, in the land which the LORD thy God giveth thee.","say":"I honour my mum and dad, just as God commanded, and it goes well with me.","theme":"friends-family","when":"obeying mum and dad","mean":"God wants me to honour my parents so my life goes well.","age":"all","tags":["friends-family"]},{"id":"deuteronomy-6-7","ref":"Deuteronomy 6:7","kjv":"And thou shalt teach them diligently unto thy children, and shalt talk of them when thou sittest in thine house, and when thou walkest by the way, and when thou liest down, and when thou risest up.","say":"In our home we talk about God, and I love learning about Him with my family.","theme":"friends-family","when":"family that loves God together","mean":"My family talks about God at home.","age":"7-9","tags":["friends-family"]},{"id":"ecclesiastes-4-10","ref":"Ecclesiastes 4:10","kjv":"For if they fall, the one will lift up his fellow: but woe to him that is alone when he falleth; for he hath not another to help him up.","say":"If my friend falls down, I can help lift them back up.","theme":"friends-family","when":"someone needs help","mean":"A good friend helps you back up when you fall.","age":"4-6","tags":["friends-family"]},{"id":"ecclesiastes-4-9","ref":"Ecclesiastes 4:9","kjv":"Two are better than one; because they have a good reward for their labour.","say":"Two friends are better than one, so I love to work and play together.","theme":"friends-family","when":"doing my schoolwork","mean":"Things go better when I have a friend to help.","age":"4-6","tags":["friends-family"]},{"id":"ephesians-6-2","ref":"Ephesians 6:2","kjv":"Honour thy father and mother; (which is the first commandment with promise;)","say":"I honour my father and mother, just like God's special command says.","theme":"friends-family","when":"obeying mum and dad","mean":"God gave a special promise to children who honour their parents.","age":"7-9","tags":["friends-family"]},{"id":"ephesians-6-3","ref":"Ephesians 6:3","kjv":"That it may be well with thee, and thou mayest live long on the earth.","say":"When I honour my parents, it goes well with me, and I can live a long life.","theme":"friends-family","when":"obeying mum and dad","mean":"God blesses me when I honour my parents.","age":"7-9","tags":["friends-family"]},{"id":"galatians-5-13","ref":"Galatians 5:13","kjv":"For, brethren, ye have been called unto liberty; only use not liberty for an occasion to the flesh, but by love serve one another.","say":"I use my hands to help, because love means I serve other people.","theme":"friends-family","when":"helping at school","mean":"Loving people means helping them.","age":"4-6","tags":["friends-family"]},{"id":"galatians-6-2","ref":"Galatians 6:2","kjv":"Bear ye one another’s burdens, and so fulfil the law of Christ.","say":"I help carry my family's heavy loads, and that makes Jesus happy.","theme":"friends-family","when":"helping at home","mean":"Helping my family is doing what Jesus wants.","age":"7-9","tags":["friends-family"]},{"id":"john-13-34","ref":"John 13:34","kjv":"A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another.","say":"Jesus loves me, so I choose to love my friends the way He loves me.","theme":"friends-family","when":"making friends","mean":"Jesus wants me to love other people.","age":"all","tags":["friends-family"]},{"id":"john-15-13","ref":"John 15:13","kjv":"Greater love hath no man than this, that a man lay down his life for his friends.","say":"The greatest love is to put my friend first, and that is how Jesus loves me.","theme":"friends-family","when":"being unselfish","mean":"The greatest love is giving up what I want for a friend.","age":"7-9","tags":["friends-family"]},{"id":"john-15-14","ref":"John 15:14","kjv":"Ye are my friends, if ye do whatsoever I command you.","say":"Jesus calls me His friend, and I love to do what He says.","theme":"friends-family","when":"obeying Jesus","mean":"I am Jesus' friend when I obey Him.","age":"4-6","tags":["friends-family"]},{"id":"leviticus-19-3","ref":"Leviticus 19:3","kjv":"Ye shall fear every man his mother, and his father, and keep my sabbaths: I am the LORD your God.","say":"I show respect to my mum and dad, because God asks me to.","theme":"friends-family","when":"obeying mum and dad","mean":"God asks me to honour my parents.","age":"7-9","tags":["friends-family"]},{"id":"luke-2-51","ref":"Luke 2:51","kjv":"And he went down with them, and came to Nazareth, and was subject unto them: but his mother kept all these sayings in her heart.","say":"Jesus obeyed His parents, and with His help I can obey mine too.","theme":"friends-family","when":"obeying mum and dad","mean":"Even Jesus listened to His mum and dad.","age":"all","tags":["friends-family"]},{"id":"mark-11-25","ref":"Mark 11:25","kjv":"And when ye stand praying, forgive, if ye have ought against any: that your Father also which is in heaven may forgive you your trespasses.","say":"When I pray, I let go and forgive anyone I'm upset with.","theme":"friends-family","when":"someone hurt me","mean":"I forgive people when I talk to God.","age":"7-9","tags":["friends-family"]},{"id":"matthew-18-22","ref":"Matthew 18:22","kjv":"Jesus saith unto him, I say not unto thee, Until seven times: but, Until seventy times seven.","say":"I can forgive again and again — even lots and lots of times.","theme":"friends-family","when":"my brother or sister","mean":"There is no limit to how much I can forgive.","age":"all","tags":["friends-family"]},{"id":"matthew-5-24","ref":"Matthew 5:24","kjv":"Leave there thy gift before the altar, and go thy way; first be reconciled to thy brother, and then come and offer thy gift.","say":"If my friend is upset with me, I go and make peace first.","theme":"friends-family","when":"making up with a friend","mean":"Making things right with others comes first.","age":"7-9","tags":["friends-family"]},{"id":"matthew-6-14","ref":"Matthew 6:14","kjv":"For if ye forgive men their trespasses, your heavenly Father will also forgive you:","say":"When I forgive others, my Father in heaven forgives me too.","theme":"friends-family","when":"someone was unkind","mean":"Forgiving others helps me be forgiven.","age":"7-9","tags":["friends-family"]},{"id":"philippians-2-4","ref":"Philippians 2:4","kjv":"Look not every man on his own things, but every man also on the things of others.","say":"I don't only think about me; I also care about what other people need.","theme":"friends-family","when":"doing my schoolwork","mean":"I think about other people too, not just me.","age":"7-9","tags":["friends-family"]},{"id":"proverbs-10-1","ref":"Proverbs 10:1","kjv":"The proverbs of Solomon. A wise son maketh a glad father: but a foolish son is the heaviness of his mother.","say":"When I am wise and obey, I make my mum and dad glad.","theme":"friends-family","when":"my family","mean":"My good choices make my parents happy.","age":"7-9","tags":["friends-family"]},{"id":"proverbs-15-17","ref":"Proverbs 15:17","kjv":"Better is a dinner of herbs where love is, than a stalled ox and hatred therewith.","say":"A small meal with love is better than a big feast full of fighting, so I bring love to our table.","theme":"friends-family","when":"a happy peaceful home","mean":"Love at home matters more than having lots of things.","age":"7-9","tags":["friends-family"]},{"id":"proverbs-17-1","ref":"Proverbs 17:1","kjv":"Better is a dry morsel, and quietness therewith, than an house full of sacrifices with strife.","say":"A quiet, peaceful home is better than a big feast full of fighting, so I help keep the peace.","theme":"friends-family","when":"a happy peaceful home","mean":"A calm, kind home is a happy home.","age":"7-9","tags":["friends-family"]},{"id":"proverbs-17-17","ref":"Proverbs 17:17","kjv":"A friend loveth at all times, and a brother is born for adversity.","say":"A good friend loves all the time, and I love my family even on hard days.","theme":"friends-family","when":"making friends","mean":"A real friend keeps loving you, even on hard days.","age":"4-6","tags":["friends-family"]},{"id":"proverbs-17-9","ref":"Proverbs 17:9","kjv":"He that covereth a transgression seeketh love; but he that repeateth a matter separateth very friends.","say":"When a friend makes a mistake, I forgive instead of telling everyone.","theme":"friends-family","when":"someone was unkind","mean":"Forgiving keeps friends close; telling tales pushes them away.","age":"7-9","tags":["friends-family"]},{"id":"proverbs-18-24","ref":"Proverbs 18:24","kjv":"A man that hath friends must shew himself friendly: and there is a friend that sticketh closer than a brother.","say":"If I want friends, I show that I am friendly and I stick close to them.","theme":"friends-family","when":"making friends","mean":"Being friendly first helps me make good friends.","age":"7-9","tags":["friends-family"]},{"id":"proverbs-23-22","ref":"Proverbs 23:22","kjv":"Hearken unto thy father that begat thee, and despise not thy mother when she is old.","say":"I listen to my dad, and I always love and respect my mum.","theme":"friends-family","when":"my family","mean":"I respect my parents, today and always.","age":"7-9","tags":["friends-family"]},{"id":"proverbs-23-24","ref":"Proverbs 23:24","kjv":"The father of the righteous shall greatly rejoice: and he that begetteth a wise child shall have joy of him.","say":"When I do what is right, my mum and dad are filled with joy.","theme":"friends-family","when":"my family","mean":"Doing right makes my parents glad.","age":"7-9","tags":["friends-family"]},{"id":"proverbs-27-10","ref":"Proverbs 27:10","kjv":"Thine own friend, and thy father’s friend, forsake not; neither go into thy brother’s house in the day of thy calamity: for better is a neighbour that is near than a brother far off.","say":"I stay close to my friends and I do not leave them, even when things get hard.","theme":"friends-family","when":"staying loyal","mean":"A good friend stays; they do not walk away.","age":"7-9","tags":["friends-family"]},{"id":"proverbs-27-17","ref":"Proverbs 27:17","kjv":"Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.","say":"Good friends help each other get better, like iron sharpens iron.","theme":"friends-family","when":"my friends and I","mean":"Good friends help each other do their best.","age":"7-9","tags":["friends-family"]},{"id":"proverbs-27-6","ref":"Proverbs 27:6","kjv":"Faithful are the wounds of a friend; but the kisses of an enemy are deceitful.","say":"A true friend tells me the truth to help me, and I can be a faithful friend too.","theme":"friends-family","when":"telling the truth kindly","mean":"A real friend tells the truth, even when it is hard.","age":"7-9","tags":["friends-family"]},{"id":"proverbs-27-9","ref":"Proverbs 27:9","kjv":"Ointment and perfume rejoice the heart: so doth the sweetness of a man’s friend by hearty counsel.","say":"A kind friend makes my heart glad, and I can make my friends glad too.","theme":"friends-family","when":"cheering a friend up","mean":"A sweet friend makes your heart happy.","age":"all","tags":["friends-family"]},{"id":"proverbs-6-20","ref":"Proverbs 6:20","kjv":"My son, keep thy father’s commandment, and forsake not the law of thy mother:","say":"I keep what my dad teaches me, and I never forget my mum's rules.","theme":"friends-family","when":"obeying mum and dad","mean":"I hold on to what my parents teach me.","age":"7-9","tags":["friends-family"]},{"id":"psalms-127-3","ref":"Psalms 127:3","kjv":"Lo, children are an heritage of the LORD: and the fruit of the womb is his reward.","say":"I am a special gift from God to my family.","theme":"friends-family","when":"loving my family","mean":"God says children are a precious gift.","age":"all","tags":["friends-family"]},{"id":"psalms-133-1","ref":"Psalms 133:1","kjv":"Behold, how good and how pleasant it is for brethren to dwell together in unity!","say":"It is so good and happy when my family lives together in love, and I help make it that way.","theme":"friends-family","when":"my brother or sister","mean":"God loves it when my family gets along.","age":"all","tags":["friends-family"]},{"id":"romans-12-18","ref":"Romans 12:18","kjv":"If it be possible, as much as lieth in you, live peaceably with all men.","say":"I do my best to live in peace with everyone.","theme":"friends-family","when":"playing with others","mean":"I try my hardest to get along with people.","age":"7-9","tags":["friends-family"]},{"id":"romans-12-21","ref":"Romans 12:21","kjv":"Be not overcome of evil, but overcome evil with good.","say":"I won't let bad feelings win — I win by doing good.","theme":"friends-family","when":"someone was unkind","mean":"I beat something bad by doing something good.","age":"7-9","tags":["friends-family"]},{"id":"1-corinthians-15-58","ref":"1 Corinthians 15:58","kjv":"Therefore, my beloved brethren, be ye stedfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord.","say":"My work for the Lord is never wasted, so I keep working hard and never give up.","theme":"wise-learner","when":"working hard at school","mean":"My hard work is never wasted.","age":"7-9","tags":["wise-learner"]},{"id":"colossians-3-23","ref":"Colossians 3:23","kjv":"And whatsoever ye do, do it heartily, as to the Lord, and not unto men;","say":"Whatever I do, I do it with all my heart for Jesus — even my schoolwork.","theme":"wise-learner","when":"doing my schoolwork","mean":"I do my schoolwork and my jobs with all my heart, for Jesus.","age":"all","tags":["wise-learner"]},{"id":"ecclesiastes-7-8","ref":"Ecclesiastes 7:8","kjv":"Better is the end of a thing than the beginning thereof: and the patient in spirit is better than the proud in spirit.","say":"I can finish what I start, because the end of a good thing is even better than the beginning!","theme":"wise-learner","when":"finishing what I start","mean":"Finishing my work is even better than starting it.","age":"7-9","tags":["wise-learner"]},{"id":"ecclesiastes-9-10","ref":"Ecclesiastes 9:10","kjv":"Whatsoever thy hand findeth to do, do it with thy might; for there is no work, nor device, nor knowledge, nor wisdom, in the grave, whither thou goest.","say":"Whatever my hand finds to do, I do it with all my might and try my very best.","theme":"wise-learner","when":"doing my best","mean":"When I have a job to do, I give it everything I have.","age":"all","tags":["wise-learner"]},{"id":"isaiah-48-17","ref":"Isaiah 48:17","kjv":"Thus saith the LORD, thy Redeemer, the Holy One of Israel; I am the LORD thy God which teacheth thee to profit, which leadeth thee by the way that thou shouldest go.","say":"The LORD my God teaches me what is good, and He leads me the right way.","theme":"wise-learner","when":"the LORD teaches me","mean":"God Himself is my teacher and leads me well.","age":"7-9","tags":["wise-learner"]},{"id":"james-1-4","ref":"James 1:4","kjv":"But let patience have her perfect work, that ye may be perfect and entire, wanting nothing.","say":"I let patience do its full work in me, so I stay calm while I learn new things.","theme":"wise-learner","when":"being patient in learning","mean":"Learning takes time, and I am patient with myself.","age":"7-9","tags":["wise-learner"]},{"id":"luke-16-10","ref":"Luke 16:10","kjv":"He that is faithful in that which is least is faithful also in much: and he that is unjust in the least is unjust also in much.","say":"I am faithful in little things and do small jobs well, so I can be trusted with more.","theme":"wise-learner","when":"doing little jobs well","mean":"If I do small things well, God trusts me with big things.","age":"7-9","tags":["wise-learner"]},{"id":"philippians-3-14","ref":"Philippians 3:14","kjv":"I press toward the mark for the prize of the high calling of God in Christ Jesus.","say":"I press on toward my goal and keep trying, all the way to the finish.","theme":"wise-learner","when":"finishing what I start","mean":"I keep going all the way to the end.","age":"7-9","tags":["wise-learner"]},{"id":"proverbs-1-5","ref":"Proverbs 1:5","kjv":"A wise man will hear, and will increase learning; and a man of understanding shall attain unto wise counsels:","say":"When I listen well, I learn more and more!","theme":"wise-learner","when":"listening in class","mean":"Listening carefully helps me learn.","age":"4-6","tags":["wise-learner"]},{"id":"proverbs-1-8","ref":"Proverbs 1:8","kjv":"My son, hear the instruction of thy father, and forsake not the law of thy mother:","say":"I listen to my dad's teaching and I keep my mum's rules, and that helps me grow wise.","theme":"wise-learner","when":"obeying mum and dad","mean":"My parents' words help me grow wise.","age":"all","tags":["wise-learner"]},{"id":"proverbs-10-4","ref":"Proverbs 10:4","kjv":"He becometh poor that dealeth with a slack hand: but the hand of the diligent maketh rich.","say":"I work hard with busy hands, and God blesses me — I won't be lazy.","theme":"wise-learner","when":"working hard at school","mean":"When I keep busy and work hard, good things come.","age":"7-9","tags":["wise-learner"]},{"id":"proverbs-12-24","ref":"Proverbs 12:24","kjv":"The hand of the diligent shall bear rule: but the slothful shall be under tribute.","say":"I work hard and do my best, and my busy, diligent hands help me do well!","theme":"wise-learner","when":"doing my best","mean":"Working hard helps me grow strong and able.","age":"7-9","tags":["wise-learner"]},{"id":"proverbs-13-1","ref":"Proverbs 13:1","kjv":"A wise son heareth his father’s instruction: but a scorner heareth not rebuke.","say":"I am a wise child, because I listen to my mum and dad.","theme":"wise-learner","when":"obeying mum and dad","mean":"Wise children listen when their parents teach them.","age":"7-9","tags":["wise-learner"]},{"id":"proverbs-13-4","ref":"Proverbs 13:4","kjv":"The soul of the sluggard desireth, and hath nothing: but the soul of the diligent shall be made fat.","say":"I don't just wish for good things; I work for them, and God makes a hard worker glad.","theme":"wise-learner","when":"doing my schoolwork","mean":"Wishing is not enough; I get up and do the work.","age":"7-9","tags":["wise-learner"]},{"id":"proverbs-18-15","ref":"Proverbs 18:15","kjv":"The heart of the prudent getteth knowledge; and the ear of the wise seeketh knowledge.","say":"I listen carefully with my ears so I can learn new things.","theme":"wise-learner","when":"paying attention","mean":"Wise people listen so they can learn.","age":"4-6","tags":["wise-learner"]},{"id":"proverbs-22-29","ref":"Proverbs 22:29","kjv":"Seest thou a man diligent in his business? he shall stand before kings; he shall not stand before mean men.","say":"When I do my very best work, God can bring me before great people, even kings.","theme":"wise-learner","when":"doing my best","mean":"When I do my best, God can take me to big places.","age":"7-9","tags":["wise-learner"]},{"id":"proverbs-24-16","ref":"Proverbs 24:16","kjv":"For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.","say":"Even good people fall down, but I get back up and try again when I make a mistake.","theme":"wise-learner","when":"trying again after a mistake","mean":"If I get it wrong, I get back up and try again.","age":"all","tags":["wise-learner"]}];
window.HEIR_PLAN=[{"month":1,"title":"January — Who I Am in Jesus","focus":"We begin the year grounding your child in the one truth every other day is built on: they are a deeply loved child and heir of God.","themeKeys":["who-i-am"]},{"month":2,"title":"February — Loved by God","focus":"All month your child declares, again and again, that God's love for them never changes and never runs out.","themeKeys":["loved-by-god","who-i-am"]},{"month":3,"title":"March — Never Alone","focus":"Your child learns that wherever they go, God is right there with them and keeping them safe, so they are never, ever alone.","themeKeys":["never-alone","protected-safe"]},{"month":4,"title":"April — Victory in Jesus","focus":"As we remember the resurrection, your child declares that in Jesus they are an overcomer who already shares His victory.","themeKeys":["victory-overcomer","brave-courage","protected-safe"]},{"month":5,"title":"May — Brave & Courageous","focus":"Standing on Jesus' victory, your child grows bold, not afraid of the dark, the new, or the hard, because God holds their hand.","themeKeys":["brave-courage","victory-overcomer","never-alone"]},{"month":6,"title":"June — Blessed & Provided For","focus":"Your child celebrates God's good gifts: His favour over their day, His provision for every need, and His healing care over their body.","themeKeys":["blessed-favour","provided-for","healthy-healed"]},{"month":7,"title":"July — Wise & Kind","focus":"Your child asks God for wisdom and lets His light shine through kind words and a helping heart.","themeKeys":["wise-learner","shine-kind","friends-family"]},{"month":8,"title":"August — Doing Right","focus":"Your child practises choosing what is right and staying calm and gentle, even when it is hard.","themeKeys":["do-right","calm-self-control","friends-family"]},{"month":9,"title":"September — Peaceful, No Worry","focus":"Your child learns to hand every worry to God and rest in His peace, right through to a calm and restful sleep.","themeKeys":["peaceful-rest","calm-self-control","restful-sleep"]},{"month":10,"title":"October — Joyful & Full of Hope","focus":"Your child's heart fills with God's joy and a bright, hopeful 'thank You' for all He is doing.","themeKeys":["joyful-hope","thankful-praise"]},{"month":11,"title":"November — Thankful & Praise","focus":"A whole month of gratitude, as your child counts God's gifts and lifts up praise with a glad and thankful heart.","themeKeys":["thankful-praise","joyful-hope"]},{"month":12,"title":"December — Faith & Prayer","focus":"We end the year strong: your child trusts God's promises, talks with Him in prayer, and looks to Jesus with joy.","themeKeys":["faith-prayer","joyful-hope","thankful-praise"]}];
